    const TOK = new Set(Array.from(TOKENIZER_CHARS));

    // かなの繰り返し記号（踊り字）。変体仮名と同じ用途で使うので同じ画面に置く。
    // くの字点は上半分と下半分の2文字を並べて1つの記号になる（縦書き用）。
    const KANA_REPEATS = [
      ["ゝ", "U+309D", "繰り返し"],
      ["ゞ", "U+309E", "繰り返し（濁点）"],
      ["ヽ", "U+30FD", "カタカナの繰り返し"],
      ["ヾ", "U+30FE", "カタカナの繰り返し（濁点）"],
      ["〳〵", "U+3033 U+3035", "くの字点"],
      ["〴〵", "U+3034 U+3035", "くの字点（濁点）"],
    ];

    // 合略仮名（2字以上を1字に詰めた字）。Unicode の DIGRAPH 系と、MJ 由来の 𬼀 (CJK拡張F)・𪜈 (拡張B)。
    const KANA_LIGATURES = [
      ["ゟ", "U+309F", "より"],
      ["ヿ", "U+30FF", "コト"],
      ["𛄣", "U+1B123", "こと"],
      ["𛄤", "U+1B124", "トキ"],
      ["𛄥", "U+1B125", "トテ"],
      ["𛄦", "U+1B126", "ヨリ"],
      ["𬼀", "U+2CF00", "して"],
      ["𪜈", "U+2A708", "とも"],
      ["〼", "U+303C", "ます"],
    ];

    // 五十音の行区分（変体仮名モードのセパレーター用）
    const GOJUON_ROWS = [
      { label: "あ行", bases: ["あ","い","う","え","お"] },
      { label: "か行", bases: ["か","き","く","け","こ"] },
      { label: "さ行", bases: ["さ","し","す","せ","そ"] },
      { label: "た行", bases: ["た","ち","つ","て","と"] },
      { label: "な行", bases: ["な","に","ぬ","ね","の"] },
      { label: "は行", bases: ["は","ひ","ふ","へ","ほ"] },
      { label: "ま行", bases: ["ま","み","む","め","も"] },
      { label: "や行", bases: ["や","ゆ","よ"] },
      { label: "ら行", bases: ["ら","り","る","れ","ろ"] },
      { label: "わ行", bases: ["わ","ゐ","ゑ","を","ん"] }
    ];

    /* =====================================================================
       初期化・ロジック
       ===================================================================== */
    function initData() {
      // JIS第1・第2水準生成
      const decoder = new TextDecoder('windows-31j');
      const ranges = [{ start: 0x889F, end: 0x9872, level: 1 }, { start: 0x989F, end: 0xEAA4, level: 2 }];
      ranges.forEach(r => {
        for (let i = r.start; i <= r.end; i++) {
          const b1 = i >> 8, b2 = i & 0xFF;
          if ((b2 >= 0x40 && b2 <= 0x7E) || (b2 >= 0x80 && b2 <= 0xFC)) {
            const char = decoder.decode(new Uint8Array([b1, b2]));
            if (char && char !== '' && /\p{Ideographic}/u.test(char)) allKanjiList[r.level].push(char);
          }
        }
      });
      // 第3・第4水準格納
      allKanjiList[3] = Array.from(JIS3_ALL).filter((v, i, a) => a.indexOf(v) === i);
      allKanjiList[4] = Array.from(JIS4_ALL).filter((v, i, a) => a.indexOf(v) === i);

      // 水準は文字が決まった時点で確定する。カードを描いた副作用で埋めていると、
      // 見えている行しか描かなくなった時に外字の判定やツリーの列が静かに狂う
      [1, 2, 3, 4].forEach(level => allKanjiList[level].forEach(c => charLevel.set(c, level)));

      // KU_RUNSをallKanjiList[level]と同じ並びの区番号配列に展開
      [1, 2, 3, 4].forEach(level => {
        KU_RUNS[level].forEach(([ku, count]) => {
          for (let i = 0; i < count; i++) kuByLevel[level].push(ku);
        });
        console.assert(kuByLevel[level].length === allKanjiList[level].length,
          `第${level}水準: 文字数(${allKanjiList[level].length})と区データ(${kuByLevel[level].length})が食い違っています`);
      });
    }

    // タブ切り替え
    function switchTab(tabId) {
      document.querySelectorAll('.tab-content').forEach(el => el.classList.remove('active'));
      document.querySelectorAll('.tab-btn').forEach(el => el.classList.remove('active'));
      document.getElementById(tabId).classList.add('active');
      event.target.classList.add('active');
      if (tabId === 'kanji') relayout(); // 隠れているあいだは幅0で測れないので、戻った時に引き直す
      syncNavH(); // 貼り付く移動の段はモードごとに別なので、高さを取り直す
    }

    // --- 漢字モードのUI制御 ---
    /* 部品の枠。枠のどこを指すかで位置を選び、その側に開く束から部品を入れる。
       位置の決め方と当たり判定は parts.js。入れた条件どうしは AND で重なる（人名用漢字や検索と同じ畳み方）。
       位置で分けられない字（⿻）と国語辞典式の部首は位置ではないので、枠の外のボタンから足す。 */
    const SLOT_LABEL = { ...PART_LABELS, 'なかみ': '中身', 'なし': '位置なし', 'ぶしゅ': '辞書の部首' };
    const slotTitle = pos => danK(pos) >= 0 ? `${stepLabel(danK(pos))}の部品` : holeK(pos) >= 0 ? `空いた所（${SLOT_LABEL[(nestHoles(nestNow())[holeK(pos)] || {}).role] || '中'}）`
      : PART_LABELS[pos] ? `${PART_LABELS[pos]}（${pos}）` : SLOT_LABEL[pos];
    // 束を開く向き。指した場所のすぐ横に出す。中身は囲いの束と重ならないよう反対側
    const PALETTE_SIDE = { 'へん': 'left', 'つくり': 'right', 'かんむり': 'top', 'あし': 'bottom',
                           'たれ': 'left', 'にょう': 'left', 'かまえ': 'right', 'なし': 'bottom', 'ぶしゅ': 'bottom' };
    const paletteSide = pos => holeK(pos) >= 0 || danK(pos) >= 0 ? 'right' : pos !== 'なかみ' ? PALETTE_SIDE[pos] : slots['かまえ'] ? 'left' : 'right';
    // 点線で見せる形。当たる場所が小さくても、字の中でその部品が占める形全体を見せる。
    // 半分どうしは間を空ける。偏と旁を両方入れたとき、塗りが繋がって枠ごと選んだように見えないように
    const ZONE_SHAPE = {
      'へん': 'M3 3H86V173H3Z', 'つくり': 'M90 3H173V173H90Z',
      'かんむり': 'M3 3H173V86H3Z', 'あし': 'M3 90H173V173H3Z',
      'たれ': 'M3 3H173V47H47V173H3Z', 'にょう': 'M3 3H47V129H173V173H3Z',
      'かまえ': 'M3 3H173V173H3Z M41 41V135H135V41Z',
    };
    // 入れた部品を描く場所（中心）と大きさ。偏や旁は半分いっぱいに、縁の位置は小さく
    const SIDE_SKIP = ['一', '丨', '丶', '丿', '乙', '亅'];
    // 空の枠に薄く置く、各区画に入る部品の見本
    const SLOT_SAMPLE = { 'へん': '亻', 'つくり': '攵', 'かんむり': '艹', 'あし': '灬', 'たれ': '广', 'にょう': '辶', 'かまえ': '門' };
    // 入れた部品のチップを置く場所。偏・旁・冠・脚は枠の辺の外、垂・繞・構・中身は角の外
    const SIDE_SPOT = { 'へん': 'l', 'つくり': 'r', 'かんむり': 't', 'あし': 'b', 'たれ': 'tl', 'にょう': 'bl', 'かまえ': 'tr', 'なかみ': 'br' };
    /* 形が似ていて取り違えやすい部品の組。干 のつもりで 宇（⿱宀于）を探して当たらない、を避ける。
       形の似た部品の公開データは見当たらないので手で持つ。足すときは 1 組 1 文字列 */
    const SIMILAR_PARTS = ['干于千', '土士', '未末', '己已巳', '日曰', '刀力', '人入八', '天夭', '王玉主壬',
      '冫氵', '礻衤', '采釆', '戊戌戍戎', '母毋', '瓜爪', '鳥烏', '大犬太', '失矢', '牛午', '夂夊',
      '卯夘', '旦且', '兔免', '貝見', '爿片', '厂广', '冂冖', '亠宀', '朩木', '儿几'];
    const similarOf = p => { const g = SIMILAR_PARTS.find(g => Array.from(g).includes(p)); return g ? Array.from(g).filter(c => c !== p) : []; };
    // 区画の範囲の中心に、区画に収まる大きさで描く（偏は左端の縦帯 24px を除いた 24〜88、冠・脚は角を除いた
    // 44〜152 の帯、垂・繞は 44px 角、構は右の角 24×44）
    const SLOT_GLYPH = {
      'へん': [56, 88, 48], 'つくり': [132, 88, 56], 'かんむり': [98, 22, 32], 'あし': [98, 154, 32],
      'たれ': [22, 22, 28], 'にょう': [22, 154, 28], 'かまえ': [164, 22, 20],
    };

    let slots = {};          // 位置 -> 部品（ぶしゅ は康熙部首の番号の文字列）
    let palettePos = null;   // 開いている束の位置
    let partsOf = null, partIndex = {}, gaijiState = 'none';   // none | building | done | old
    const slotCache = new Map();
    const enclosureOf = sl => ['かまえ', 'たれ', 'にょう'].find(p => sl[p]) || null;
    const enclosure = () => nestMode ? null : enclosureOf(slots);
    const lookupIds = c => PART_IDS[c] || (mjmap && mjmap.ids ? mjmap.ids[c] : undefined);

    /* 入れ子で組むモード。枠で選んだ順（nestSteps）から内側から外へ形を組み、その形を含む字を引く。
       形の組み方と照合は parts.js の nestStep / makeNest。位置でない なし・辞書の部首は、どちらのモードでも slots に持つ。
       枠では、いままでの形を真ん中に描き、周りの環で外を包む位置を、形の中の穴（あな0, あな1…）で埋める所を指す */
    // 使う場面は「字の画像を見ながら同じ字を探す」なので、形が見えている前提の入れ子を既定にする
    let nestMode = true, nestSteps = [], nestM = null, nestUniverse = [];
    const nestCache = new Map();
    const NEST_FREE = ['なし', 'ぶしゅ'];
    const nestNow = () => nestTree(nestSteps);
    const isNestPos = pos => nestMode && !NEST_FREE.includes(pos);
    const holeK = pos => /^あな\d+$/.test(pos || '') ? +pos.slice(2) : -1;
    const danK = pos => /^だん\d+$/.test(pos || '') ? +pos.slice(2) : -1;   // 前に選んだ段の部品（押すと入れ替える）
    // 束の位置から段を作る。穴は行きがけ順の番号で持つ
    const nestStepOf = (pos, part) => holeK(pos) >= 0 ? ['あな', part, nestHoles(nestNow())[holeK(pos)].path] : [pos, part];
    // 段 i の部品が、いまの形のどこにあるか（根からの経路）。後の段が外を包むたびに、包まれた側の番号が前に付く
    function stepPath(steps, i) {
      let path = steps[i][0] === 'あな' ? steps[i][2] : [NEST_OP[steps[i][0]][1]];
      for (let j = i + 1; j < steps.length; j++) if (steps[j][0] !== 'あな') path = [1 - NEST_OP[steps[j][0]][1], ...path];
      return path;
    }
    // 束の位置で部品を選んだあとの段の並び。環は外を包む段を、穴は埋める段を足し、前に選んだ部品はその段の部品を替える
    function withPick(pos, part) {
      const k = danK(pos);
      if (k >= 0) return nestSteps.map((st, j) => j === k ? [st[0], part, st[2]].slice(0, st.length) : st);
      return [...nestSteps, nestStepOf(pos, part)];
    }
    // 段の呼び名。穴を埋めた段は、その穴が字のどの位置か（偏・中身…）で呼ぶ
    function stepLabel(i) {
      const [pos, , path] = nestSteps[i];
      if (pos !== 'あな') return SLOT_LABEL[pos];
      const h = nestHoles(nestTree(nestSteps.slice(0, i))).find(h => h.path.join() === path.join());
      return SLOT_LABEL[h && h.role] || '穴';
    }
    /* 段を外す。途中の位置の段は、部品だけを穴に戻して形は残す（後の段の位置と、穴埋めの経路を変えないため）。
       穴埋めの段と最後の段はそのまま抜く。抜いたあと外側に残った部品の無い段は、形の意味が無いので落とす */
    function dropStep(steps, i) {
      const out = i === steps.length - 1 || steps[i][0] === 'あな'
        ? steps.filter((_, j) => j !== i) : steps.map((st, j) => j === i ? [st[0], null] : st);
      while (out.length && out[out.length - 1][0] !== 'あな' && out[out.length - 1][1] == null) out.pop();
      return out.some(st => st[1] != null) ? out : [];
    }
    // 条件として効いている slots。入れ子のときは なし・辞書の部首だけ（ラフで入れた部品は残すが効かせない）
    const liveSlots = () => nestMode ? Object.fromEntries(Object.entries(slots).filter(([p]) => NEST_FREE.includes(p))) : slots;
    function nestChars(t) {
      const key = nestText(t);
      let set = nestCache.get(key);
      if (!set) nestCache.set(key, set = new Set(nestUniverse.filter(c => nestM.test(c, t))));
      return set;
    }
    // pos に部品を足したときの字を、部品ごとに 1 回の照合でまとめて引く（その位置に来た部品 -> 字）
    function nestPicks(pos) {
      const key = `${pos}\t${nestText(nestNow())}`;
      let m = nestCache.get(key);
      if (m) return m;
      const t = nestTree(withPick(pos, CAPTURE));
      nestCache.set(key, m = new Map());
      for (const c of nestUniverse) {
        const cap = nestM.capture(c, t);
        if (cap) new Set(cap).forEach(p => { let s = m.get(p); if (!s) m.set(p, s = new Set()); s.add(c); });
      }
      return m;
    }

    /* 枠の環。形を真ん中の四角に描き、その周りの帯で外を包む位置を指す。帯の割り振りは空の枠と同じ向き
       （上=冠、下=脚、左=偏、右=旁、左上の角=垂、左下の角=繞、右の角と枠の外=構） */
    const RING = 32;
    /* 形を描く範囲。一番外で空いている側は、環の帯まで広げて空いた所と 1 つの区画にする
       （帯と穴が同じ意味の別の区画として並ぶと、どちらを指しても同じ所が光って紛らわしい） */
    function shapeRect() {
      const S = BOX.size, R = RING, rf = ringFills();
      return [rf['へん'] ? 0 : R, rf['かんむり'] ? 0 : R, rf['つくり'] ? S : S - R, rf['あし'] ? S : S - R];
    }
    /* ⿰⿱ の左右（上下）の割合は、両側の本来の縦横比で分ける。偏が細いとは限らず、郡（⿰君阝）は右の 阝 が細い。
       決め打ちの割合だと、広い字が狭い側に押し込まれて小さく、細い字が広い側で大きく描かれる。
       縦横比（幅 / 高さ）は、部品は墨の範囲、穴と囲いは正方形、⿰ は高さを揃えて幅を足し、⿱ は幅を揃えて高さを足す */
    function natAspect(n) {
      if (isHole(n) || NEST_ENCL.includes(n.op)) return 1;
      if (typeof n === 'string') {
        const [L, R, A, D] = inkBox(n);
        return L + R > 0 && A + D > 0 ? Math.min(Math.max((L + R) / (A + D), .25), 4) : 1;
      }
      const [a, b] = n.args.map(natAspect);
      return n.op === '⿰' ? a + b : 1 / (1 / a + 1 / b);
    }
    function nestSplit(n) {
      const [a, b] = n.args.map(natAspect);
      const clamp = f => Math.min(Math.max(f, .25), .75);
      if (n.op === '⿰') { const f = clamp(a / (a + b)); return [[0, 0, f, 1], [f, 0, 1, 1]]; }
      if (n.op === '⿱') { const f = clamp((1 / a) / (1 / a + 1 / b)); return [[0, 0, 1, f], [0, f, 1, 1]]; }
      return IDS_RECTS[n.op];
    }
    let hitRects = [];    // 描いた穴（あな）と部品（だん）の { r: 範囲, z: 区画 }（行きがけ順）。当たり判定とキーボードの区画に使う
    /* 一番外が ⿰⿱ でその片側が空いているときは、その側の環は外を包まずに空いた所を埋める。
       冠だけを入れた形で、下の環（脚で包む）と空いた所（脚を埋める）が同じ意味の 2 通りになるのを避ける。
       環の位置 -> 穴の番号 */
    function ringFills() {
      const t = nestNow(), out = {};
      if (!t || !NEST_ROLE[t.op]) return out;
      const holes = nestHoles(t);
      t.args.forEach((a, i) => {
        if (isHole(a)) out[NEST_ROLE[t.op][i]] = 'あな' + holes.findIndex(h => h.path.join() === String(i));
      });
      return out;
    }
    function nestZone(x, y) {
      const S = BOX.size, H = BOX.halo;
      if (x < -H || y < -H || x >= S + H || y >= S + H) return null;
      if (x < 0 || y < 0 || x >= S || y >= S) return 'かまえ';
      // 囲いの字の範囲の中に中身があるので、重なるところは内側を優先する。内側ほど後に描いている
      const h = hitRects.findLast(({ r }) => x >= r[0] && x < r[2] && y >= r[1] && y < r[3]);
      if (h) return h.z;
      const l = x < RING, r = x >= S - RING, t = y < RING, b = y >= S - RING;
      if (l && t) return 'たれ';
      if (l && b) return 'にょう';
      if (r && (t || b)) return 'かまえ';
      return t ? 'かんむり' : b ? 'あし' : l ? 'へん' : r ? 'つくり' : null;   // 形の上（穴でない所）は何もしない
    }
    // 環の位置を指したときの点線。当たる角や帯ではなく、包んだあとにその部品が占める形全体を見せる
    function nestZoneShape(pos) {
      const S = BOX.size, R = RING, h = hitRects.find(h => h.z === pos);
      if (h) return rectPath(h.d);
      return {
        'かんむり': rectPath([0, 0, S, R]), 'あし': rectPath([0, S - R, S, S]),
        'へん': rectPath([0, 0, R, S]), 'つくり': rectPath([S - R, 0, S, S]),
        'たれ': `M0 0H${S}V${R}H${R}V${S}H0Z`, 'にょう': `M0 0H${R}V${S - R}H${S}V${S}H0Z`,
        'かまえ': rectPath([0, 0, S, S]) + rectPath(shapeRect()),
      }[pos] || '';
    }

    /* 索引。水準字は 36ms で組めるのですぐ組み、外字（4 万字、まとめると 1 秒止まる）は
       mjmap を読んだあと 2,000 字ずつ空き時間に足す。mjmap を読み直したら最初から組み直す。 */
    let indexJob = 0;
    function initPartIndex() {
      indexJob++;
      partsOf = makeParts(lookupIds);
      partIndex = buildPartIndex([1, 2, 3, 4].flatMap(lv => allKanjiList[lv]), partsOf);
      slotCache.clear();
      nestM = makeNest(lookupIds, partForms);
      nestUniverse = [1, 2, 3, 4].flatMap(lv => allKanjiList[lv]);
      nestCache.clear();
      gaijiState = 'none';
    }
    function indexGaiji() {
      initPartIndex();
      if (!mjmap.ids) { gaijiState = 'old'; return; }   // IDS を持たない古い mjmap.json
      const job = indexJob;
      const chars = [...new Set(mjBase.filter(c => c && !charLevel.has(c)))];
      // 入れ子の照合は 5 万字でも数十 ms なので、索引を待たずに外字も入れる
      nestUniverse = nestUniverse.concat(chars);
      gaijiState = 'building';
      let i = 0;
      const step = () => {
        if (job !== indexJob) return;
        buildPartIndex(chars.slice(i, i + 2000), partsOf, partIndex);
        i += 2000;
        if (i < chars.length) { setTimeout(step, 0); return; }
        slotCache.clear();
        gaijiState = 'done';
        renderKanji();
      };
      setTimeout(step, 0);
    }

    // 人 と打って 亻 にも当てる。親字には位置別の字体を足すが、字体から親字へは広げない（月 から 肉 は引かない）
    /* 同じ部品の書き方の揺れ。IDS の出典で 甾 は 巛、畄 は 𭕄 と書かれていて、片方で選ぶともう片方が引けない。
       似た部品（SIMILAR_PARTS、取り違えの直し先）と違い、どちらで選んでも両方に当てる。足すときは 1 組 1 文字列 */
    const PART_ALIKE = ['巛𭕄'];
    const partForms = p => {
      const g = PART_ALIKE.find(g => Array.from(g).includes(p));
      return (g ? Array.from(g) : [p]).flatMap(q => [q, ...Object.keys(RADICAL_FAMILY).filter(v => RADICAL_FAMILY[v] === q)]);
    };
    function slotChars(pos, part) {
      const key = `${pos}\t${part}`;
      let set = slotCache.get(key);
      if (set) return set;
      set = new Set();
      if (pos === 'ぶしゅ') {
        for (const c of DICT_RADICALS[part] || '') set.add(c);
        for (const c of (mjmap && mjmap.dictRadicals && mjmap.dictRadicals[part]) || '') set.add(c);
      } else if (partIndex[pos]) {
        partForms(part).forEach(f => (partIndex[pos].get(f) || []).forEach(c => set.add(c)));
      }
      slotCache.set(key, set);
      return set;
    }
    // 枠の条件で残る字（null はすべて）。except の位置の部品は外し、入れ子の形は steps で組む
    function frameChars(except, steps = nestMode ? nestSteps : []) {
      let T = null;
      const live = liveSlots();
      for (const pos in live) {
        if (pos === except) continue;
        const s = slotChars(pos, live[pos]);
        T = T ? new Set([...T].filter(c => s.has(c))) : s;
      }
      if (steps.length) {
        const s = nestChars(nestTree(steps));
        T = T ? new Set([...T].filter(c => s.has(c))) : s;
      }
      return T;
    }
    // 束の件数の母数。その束の位置に入っている部品は外して数える（入れ替えた先の件数を見せるため）
    function conditionChars(except, steps) {
      let T = frameChars(except, steps);
      if (el('onlyJinmei').checked) T = new Set([...(T || JINMEI_CHARS)].filter(c => JINMEI_CHARS.has(c)));
      return T;
    }
    function countIn(T, S) {
      if (!T) return S.size;
      let n = 0;
      const [a, b] = T.size < S.size ? [T, S] : [S, T];
      for (const c of a) if (b.has(c)) n++;
      return n;
    }
    // 束のチップの件数。入れ子の位置は、いまの形にその部品を 1 段足したときに当たる字数
    function partCount(pos, part, T) {
      if (!isNestPos(pos)) return countIn(T, slotChars(pos, part));
      const m = nestPicks(pos), s = new Set();
      partForms(part).forEach(f => (m.get(f) || []).forEach(c => s.add(c)));
      return countIn(T, s);
    }
    const slotGlyph = (pos, part) => pos === 'ぶしゅ' ? String.fromCodePoint(0x2F00 + +part - 1).normalize('NFKC') : part;
    const readingOf = part => { for (const pos in RADICAL_READING) if (RADICAL_READING[pos][part]) return RADICAL_READING[pos][part]; return ''; };

    /* 束に並べるチップ。7 位置は部首チップと同じ顔ぶれ（呼び名のある部首を先に、残りは 20 字以上に現れる部品）。
       中身と位置なしは呼び名が無いので字数の多い順、辞書の部首は 214 部首を字数の多い順。 */
    function paletteChips(pos) {
      // 穴は形が決まっているので、その穴に実際に来る部品を字数の多い順に並べる
      if (holeK(pos) >= 0 || danK(pos) >= 0) {
        return [...nestPicks(pos)].filter(([p]) => p !== '?' && !isPlaceholder(p) && !SIDE_SKIP.includes(p)).sort((a, b) => b[1].size - a[1].size)
          .map(([part]) => ({ part, glyph: part, yomi: readingOf(part), named: false }));
      }
      if (pos === 'ぶしゅ') {
        return DICT_RADICAL_NAMES.map((yomi, i) => ({ part: String(i + 1), glyph: slotGlyph('ぶしゅ', i + 1), yomi, named: true }))
          .map(c => ({ ...c, size: slotChars('ぶしゅ', c.part).size })).filter(c => c.size)
          .sort((a, b) => b.size - a.size);
      }
      if (RADICAL_CHIPS[pos]) {
        return RADICAL_CHIPS[pos].map((part, i) => ({
          part, glyph: part, yomi: (RADICAL_READING[pos] || {})[part] || '', named: i < RADICAL_REAL[pos] }));
      }
      return [...(partIndex[pos] || new Map())].filter(([, s]) => s.size >= 20)
        .sort((a, b) => b[1].size - a[1].size)
        .map(([part]) => ({ part, glyph: part, yomi: readingOf(part), named: false }));
    }

    function buildRadicalListboxes() {
      const wrap = el('radicalListboxes');
      const area = document.createElement('div');
      area.className = 'pbox-area';
      area.innerHTML = `
        <div class="pbox-mode" role="radiogroup" aria-label="枠の使い方">
          <button type="button" role="radio" data-nest="1" title="内側の部首から順に選び、外側へ積み上げて字を組み立てる。偏→冠 と 冠→偏 で形が変わる">組立検索</button>
          <button type="button" role="radio" data-nest="0" title="入っている部首と、それが字のどの辺りにあるかで絞る。選ぶ順は問わない">部首検索</button>
        </div>
        <div class="pbox" id="pbox">
          <div class="pbox-hit" id="pboxHit">
            <div class="pbox-halo" aria-hidden="true"></div>
            <div class="pbox-frame" id="pboxFrame">
              <svg viewBox="0 0 176 176" aria-hidden="true">
                <g class="pbox-fills" id="pboxFills"></g>
                <g class="pbox-guides" id="pboxGuides"></g>
                <path class="pbox-shape" id="pboxShape" d="" hidden></path>
              </svg>
              <div class="pbox-glyphs" id="pboxGlyphs" aria-hidden="true"></div>
              <div class="pbox-hint" id="pboxHint" aria-hidden="true"></div>
              <div class="pbox-keys" id="pboxKeys" role="group" aria-label="部品の位置"></div>
            </div>
          </div>
          <div class="pbox-sides" id="pboxSides"></div>
          <div class="palette" id="partPalette" role="dialog" aria-modal="false" hidden></div>
        </div>
        <div class="pbox-status">
          <div class="pbox-label" id="pboxLabel" aria-live="polite"></div>
          <div class="pbox-clear" id="pboxClear"></div>
        </div>
        <div class="pbox-extra">
          <button type="button" class="pbox-btn" data-pos="なし"></button>
          <button type="button" class="pbox-btn" data-pos="ぶしゅ"></button>
        </div>
        <div class="pbox-info" id="condBar" aria-live="polite"></div>
        <div class="char-parts" id="charParts" hidden></div>`;
      // 左に枠、右に検索・絞り込み・条件・件数。探す操作と、その結果の確かめを横に並べる
      const finder = document.createElement('div');
      finder.className = 'finder';
      const side = document.createElement('div');
      side.className = 'finder-side';
      side.append(el('searchRow'), el('filterRow'), ...area.querySelectorAll('.pbox-extra, #condBar, #charParts'));
      finder.append(area, side);
      wrap.appendChild(finder);

      // 右の列へ移したあとなので、枠の中ではなく文書全体から探す
      document.querySelectorAll('.pbox-btn').forEach(b => { b.onclick = () => openPalette(b.dataset.pos); });
      document.querySelectorAll('.pbox-mode button').forEach(b => {
        b.onclick = () => { nestMode = b.dataset.nest === '1'; syncMode(); closePalette(); pushNext = true; renderKanji(); };
      });
      syncMode();
      wirePbox();
      drawPbox();
    }

    const syncMode = () => document.querySelectorAll('.pbox-mode button').forEach(b => b.setAttribute('aria-checked', (b.dataset.nest === '1') === nestMode));

    /* ---- 枠の描画と操作 ---- */
    let previewPos = null;
    function preview(pos) {
      previewPos = pos;
      const shape = el('pboxShape');
      const d = nestMode && nestSteps.length ? nestZoneShape(pos) : pos === 'なかみ' ? innerPath() : ZONE_SHAPE[pos];
      shape.toggleAttribute('hidden', !d);   // SVG の要素は hidden プロパティを持たない
      if (d) shape.setAttribute('d', d);
      el('pboxLabel').textContent = pos ? slotTitle(pos) : '';
      // 指した穴は、いつもの細い点線を隠して指したときの点線だけにする（刻みの違う点線が 2 本重なって見えないように）
      document.querySelectorAll('#pboxFills path.hole').forEach(h => h.classList.toggle('off', h.dataset.z === pos));
    }
    function innerPath() {
      const o = innerOrigin(enclosure());
      return o ? `M${o[0]} ${o[1]}h${BOX.inner}v${BOX.inner}h-${BOX.inner}Z` : '';
    }
    /* 部品の字を、墨の中心が (x, y) に来るように置く。亻 は字の枠の左寄り、灬 は下寄り、艹 は上寄りに
       作られているので、字の枠の中心で揃えると区画からずれて見える。墨の範囲は canvas で測る。
       Web フォントが届く前の測り値は捨て、届いたら測り直して描き直す */
    const inkCache = new Map();
    let inkCtx = null;
    function inkCenter(ch, size) {
      const key = `${size}\t${ch}`;
      if (inkCache.has(key)) return inkCache.get(key);
      inkCtx = inkCtx || document.createElement('canvas').getContext('2d');
      inkCtx.font = `${size}px "Noto Serif JP", serif`;
      inkCtx.textAlign = 'center';
      inkCtx.textBaseline = 'middle';
      const m = inkCtx.measureText(ch);
      const c = [(m.actualBoundingBoxRight - m.actualBoundingBoxLeft) / 2, (m.actualBoundingBoxDescent - m.actualBoundingBoxAscent) / 2];
      if (!document.fonts || document.fonts.check(inkCtx.font, ch)) inkCache.set(key, c);
      return c;
    }
    function glyphSpan(ch, x, y, size) {
      const [dx, dy] = inkCenter(ch, size);
      return `<span style="left:${(x - dx).toFixed(1)}px;top:${(y - dy).toFixed(1)}px;font-size:${size}px">${ch}</span>`;
    }
    if (document.fonts) document.fonts.addEventListener('loadingdone', () => { inkCache.clear(); inkBoxCache.clear(); innerCache.clear(); if (el('pboxFrame')) drawPbox(); });

    const rectPath = r => `M${r[0]} ${r[1]}H${r[2]}V${r[3]}H${r[0]}Z`;
    const inset = (r, d) => [r[0] + d, r[1] + d, r[2] - d, r[3] - d];
    // 区画の形に合わせて字を伸び縮みさせて描く。偏は細く、冠は平たく、実際の字の中の姿に近づける
    /* 字の墨の範囲（100px で測った左・右・上・下の張り出し）。inkCenter と同じく、Web フォントが届く前の値は覚えない */
    const inkBoxCache = new Map();
    function inkBox(ch) {
      if (inkBoxCache.has(ch)) return inkBoxCache.get(ch);
      inkCtx = inkCtx || document.createElement('canvas').getContext('2d');
      inkCtx.font = '100px "Noto Serif JP", serif';
      inkCtx.textAlign = 'center';
      inkCtx.textBaseline = 'middle';
      const m = inkCtx.measureText(ch);
      const b = [m.actualBoundingBoxLeft, m.actualBoundingBoxRight, m.actualBoundingBoxAscent, m.actualBoundingBoxDescent];
      if (!document.fonts || document.fonts.check(inkCtx.font, ch)) inkBoxCache.set(ch, b);
      return b;
    }
    /* 区画に合わせて字を描く。字の箱ではなく墨の範囲を区画に収めるので、もともと細い 亻 や平たい 艹 はそのままの形で
       区画いっぱいになる。木 を偏の幅に入れるような縦横の違う区画では伸び縮みさせるが、縦横の差は 1.25 倍までにして、
       つぶれたり線が太りすぎたりしないようにする（収まらない分は小さく描く） */
    const stretchGlyph = (ch, r) => glyphFit(ch, r).html;
    // 描いた字の html と、墨の範囲（枠の px）。墨を測れないときの範囲は区画そのもの
    function glyphFit(ch, r) {
      const w = (r[2] - r[0]) * .9, h = (r[3] - r[1]) * .9, cx = (r[0] + r[2]) / 2, cy = (r[1] + r[3]) / 2;
      const [L, R, A, D] = inkBox(ch);
      if (!(L + R > 0 && A + D > 0)) return { html: glyphSpan(ch, cx, cy, Math.min(w, h)), ink: r };
      let kx = w / (L + R), ky = h / (A + D);
      const u = Math.min(kx, ky);
      kx = Math.min(kx, u * 1.25);
      ky = Math.min(ky, u * 1.25);
      // 拡大は字の箱の中心まわりにかかるので、墨の中心のずれも同じ倍率で動く
      const x = cx - (R - L) / 2 * kx, y = cy - (D - A) / 2 * ky;
      const iw = (L + R) * kx / 2, ih = (A + D) * ky / 2;
      return {
        html: `<span style="left:${x.toFixed(1)}px;top:${y.toFixed(1)}px;font-size:${(100 * u).toFixed(1)}px;`
          + `transform:translate(-50%,-50%) scale(${(kx / u).toFixed(3)},${(ky / u).toFixed(3)})">${ch}</span>`,
        ink: [cx - iw, cy - ih, cx + iw, cy + ih],
      };
    }
    /* 囲いの字の中の空いている所（墨の範囲を 0〜1 とした割合）。中身を IDS の決め打ちの割合で置くと、
       尸 の上の箱のように囲いの字の形によっては重なるので、字を描いて測る。中身が来る側の点（⿸ は右下、
       ⿺ は右上、構は真ん中）を含む、墨の無い長方形のうち、正方形に近くて広いものを選ぶ */
    const INNER_SEED = { '⿸': [.75, .75], '⿺': [.75, .3], '⿴': [.5, .5] };
    const innerCache = new Map();
    function emptyInside(ch, op) {
      const key = `${op}\t${ch}`;
      if (innerCache.has(key)) return innerCache.get(key);
      const N = 48, [L, R, A, D] = inkBox(ch);
      if (!(L + R > 0 && A + D > 0)) return null;
      const cv = document.createElement('canvas');
      cv.width = cv.height = N;
      const ctx = cv.getContext('2d', { willReadFrequently: true });
      ctx.font = '100px "Noto Serif JP", serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.setTransform(N / (L + R), 0, 0, N / (A + D), L * N / (L + R), A * N / (A + D));
      ctx.fillText(ch, 0, 0);
      const px = ctx.getImageData(0, 0, N, N).data;
      const ink = (x, y) => px[(y * N + x) * 4 + 3] > 40;
      const [sx, sy] = INNER_SEED[op].map(v => Math.floor(v * N));
      let best = null, score = 0;
      for (let y0 = sy; y0 >= 0; y0--) {
        for (let y1 = sy; y1 < N; y1++) {
          const clear = x => { for (let y = y0; y <= y1; y++) if (ink(x, y)) return false; return true; };
          if (!clear(sx)) break;
          let x0 = sx, x1 = sx;
          while (x0 > 0 && clear(x0 - 1)) x0--;
          while (x1 < N - 1 && clear(x1 + 1)) x1++;
          const w = x1 - x0 + 1, h = y1 - y0 + 1, sc = w * h * Math.min(w / h, h / w);
          if (sc > score) { score = sc; best = [x0 / N, y0 / N, (x1 + 1) / N, (y1 + 1) / N]; }
        }
      }
      // 小さすぎるときは測り違い（字が届く前など）とみなして決め打ちの割合に任せる
      if (best && (best[2] - best[0]) * (best[3] - best[1]) < .08) best = null;
      if (!document.fonts || document.fonts.check(ctx.font, ch)) innerCache.set(key, best);
      return best;
    }
    /* 入れ子の形を枠に描く。いままでの形は真ん中の四角に、外を包むたびに一回り小さくなって入る。
       囲いの字は範囲いっぱいに描き、中身はその上に重ねる。穴（何でもよい所）は点線の四角で、押すとそこを埋める。
       周りの環には、各位置に入る部品の見本を薄く置く（空の枠の見本と同じ役目） */
    function drawNest() {
      const S = BOX.size, R = RING, fills = [], glyphs = [];
      hitRects = [];
      if (!nestSteps.length) return;
      // 形の中の部品から、それを選んだ段へ。部品を穴に戻した段は持たない。古い経路の穴埋めは先の段に譲る
      const owner = new Map();
      nestSteps.forEach((st, i) => { const k = stepPath(nestSteps, i).join(); if (st[1] != null && !owner.has(k)) owner.set(k, i); });
      let holes = 0;
      // 指したときの点線（d）は、描いた点線・塗りと同じ四角に重ねる。当たる範囲（r）より内側に描いているので、
      // r で引くと常に見えている穴の点線と数 px ずれて二重に見える
      const hole = r => {
        const z = 'あな' + holes++;
        hitRects.push({ r, z, d: inset(r, 3) });
        fills.push(`<path class="hole" data-z="${z}" d="${rectPath(inset(r, 3))}"/>`);
      };
      const part = (ch, r, path) => { if (owner.has(path.join())) hitRects.push({ r, z: 'だん' + owner.get(path.join()), d: inset(r, 1) }); };
      (function walk(n, r, path) {
        if (isHole(n)) { hole(r); return; }
        if (typeof n === 'string') {
          part(n, r, path);
          fills.push(`<path d="${rectPath(inset(r, 1))}"/>`);
          glyphs.push(stretchGlyph(n, inset(r, 3)));
          return;
        }
        const [a, b] = nestSplit(n).map(f => sub(r, f));
        if (NEST_ENCL.includes(n.op)) {
          let inner = b;
          if (isHole(n.args[0])) hole(a);
          else {
            const g = glyphFit(n.args[0], inset(a, 3)), e = emptyInside(n.args[0], n.op), k = g.ink;
            part(n.args[0], a, [...path, 0]);
            glyphs.push(g.html);
            if (e) inner = inset([k[0] + (k[2] - k[0]) * e[0], k[1] + (k[3] - k[1]) * e[1], k[0] + (k[2] - k[0]) * e[2], k[1] + (k[3] - k[1]) * e[3]], 2);
          }
          fills.push(`<path d="${rectPath(inset(a, 1))}${rectPath(inset(inner, -1))}"/>`);
          walk(n.args[1], inner, [...path, 1]);
          return;
        }
        walk(n.args[0], a, [...path, 0]);
        walk(n.args[1], b, [...path, 1]);
      })(nestNow(), shapeRect(), []);
      // 環の区切りは角を分ける短い線だけ。形の範囲は塗りと穴の点線で見えるので、外枠も引くと穴の点線と並んで二重に見える
      const ring = `M${R} 0V${R}H0M${S - R} 0V${R}H${S}M${R} ${S}V${S - R}H0M${S - R} ${S}V${S - R}H${S}`;
      el('pboxFills').innerHTML = `<path class="ring" d="${ring}"/>` + fills.join('');
      el('pboxGlyphs').innerHTML = glyphs.join('');
      const spot = { 'かんむり': [S / 2, R / 2], 'あし': [S / 2, S - R / 2], 'へん': [R / 2, S / 2], 'つくり': [S - R / 2, S / 2],
                     'たれ': [R / 2, R / 2], 'にょう': [R / 2, S - R / 2], 'かまえ': [S - R / 2, R / 2] };
      const fills2 = ringFills();
      el('pboxHint').innerHTML = Object.keys(spot).filter(p => !fills2[p]).map(p => glyphSpan(SLOT_SAMPLE[p], spot[p][0], spot[p][1], 22)).join('');
    }

    function drawPbox() {
      const { size: S, band: B, strip: W, cornerW: CW, cornerH: CH } = BOX;
      // 区画の線。垂・繞は当たり判定のとおり L 字の外形で引き、L の中（角と縦帯の間）には線を入れない。
      // 垂と繞の境は 1 本だけ引く（2 本重ねると点線の位相がずれて実線に見える）。
      // 冠・脚の帯の線は L 字の角の外から、構は右の角の四角
      el('pboxGuides').innerHTML =
        `<path d="M${B} 0V${B}H${W}V${S / 2}"/><line x1="0" y1="${S / 2}" x2="${W}" y2="${S / 2}"/><path d="M${W} ${S / 2}V${S - B}H${B}V${S}"/>
         <line x1="${B}" y1="${B}" x2="${S - CW}" y2="${B}"/><line x1="${B}" y1="${S - B}" x2="${S - CW}" y2="${S - B}"/>
         <line x1="${S / 2}" y1="${B}" x2="${S / 2}" y2="${S - B}"/><path d="M${S - CW} 0V${CH}H${S}"/><path d="M${S - CW} ${S}V${S - CH}H${S}"/>`
        + (enclosure() ? `<path d="${innerPath()}"/>` : '');
      const framed = nestMode ? nestSteps : Object.keys(slots).filter(p => !NEST_FREE.includes(p));
      el('pboxFrame').classList.toggle('empty', !framed.length);
      el('pboxFills').innerHTML = Object.keys(liveSlots()).filter(p => ZONE_SHAPE[p] || p === 'なかみ')
        .map(p => `<path d="${p === 'なかみ' ? innerPath() : ZONE_SHAPE[p]}"/>`).join('');
      // 何も入れていないときは、入力欄の placeholder のように、各区画に入る部品の見本を薄く置く。
      // 部品を入れたあとと同じ場所・同じ大きさに描くので、入れたあとの姿の予告になる
      el('pboxHint').innerHTML = framed.length ? '' : Object.keys(SLOT_GLYPH).map(p => {
        const [x, y, size] = SLOT_GLYPH[p];
        return glyphSpan(SLOT_SAMPLE[p], x, y, size);
      }).join('');
      const o = innerOrigin(enclosure());
      el('pboxGlyphs').innerHTML = Object.keys(liveSlots()).filter(p => SLOT_GLYPH[p] || p === 'なかみ').map(p => {
        const [x, y, size] = p === 'なかみ' ? [o[0] + BOX.inner / 2, o[1] + BOX.inner / 2, 32] : SLOT_GLYPH[p];
        return glyphSpan(slots[p], x, y, size);
      }).join('');
      if (nestMode) drawNest();
      // キーボードでは区画をボタンとして順に移る。フォーカスした区画はホバーと同じく点線で見せる
      const rf = nestMode ? ringFills() : {};
      const keys = ['かんむり', 'たれ', 'へん', 'つくり', 'にょう', 'あし', 'かまえ'].filter(p => !rf[p])
        .concat(enclosure() ? ['なかみ'] : [], nestMode ? hitRects.map(h => h.z) : []);
      el('pboxKeys').innerHTML = keys.map(p =>
        `<button type="button" data-pos="${p}" aria-label="${slotTitle(p)}${!nestMode && slots[p] ? `：${slots[p]}` : ''}"></button>`).join('');
      // 入れた部品は、束で選んだときのチップ（字と件数）のまま、枠の外のその側に出しておく。
      // 隣には同じ位置の他の候補を、いまの条件で残る字数の多い順に並べ、押せばそのまま入れ替わる
      el('pboxSides').innerHTML = '';
      const lists = {};
      const chip = (pos, part, n, selected, similar) => {
        const b = document.createElement('button');
        b.type = 'button';
        b.className = 'pchip side-chip' + (similar ? ' similar' : '');
        b.setAttribute('aria-selected', selected);
        b.title = `${similar ? '似た部品　' : ''}${slotTitle(pos)}：${part}・${n}字`;
        b.innerHTML = '<span class="g"></span><span class="n"></span>';
        b.querySelector('.g').textContent = part;
        b.querySelector('.n').textContent = n;
        b.onclick = () => setSlot(pos, selected ? null : part);   // 選択中を押したらそのまま外す
        return b;
      };
      Object.keys(liveSlots()).filter(p => SIDE_SPOT[p]).forEach(pos => {
        // 置き場所は位置ごとに固定する。同じ側の位置（偏・垂・繞）を1つの入れ物にまとめると、
        // どれかを入れ外しするたびに並びが組み直されて揺れる
        const spot = SIDE_SPOT[pos];
        const list = lists[spot] = Object.assign(document.createElement('div'), { className: `side-list side-${spot}` });
        const T = conditionChars(pos);
        list.appendChild(chip(pos, slots[pos], countIn(T, slotChars(pos, slots[pos])), true));
        // 先頭に形の似た部品（取り違えの直し先）、続けて呼び名のある部首を先に件数の多い順。
        // 1 画の部首は大抵の字に含まれ候補として役に立たないので出さない。
        // 左右は枠の高さ（2 列 4 段）、上下は枠の幅に収まる数まで
        const similar = similarOf(slots[pos]).map(p => [p, countIn(T, slotChars(pos, p))]).filter(([, n]) => n);
        const others = paletteChips(pos).filter(c => c.part !== slots[pos] && !SIDE_SKIP.includes(c.part) && !similar.some(([p]) => p === c.part))
          .map(c => [c.part, countIn(T, slotChars(pos, c.part)), c.named]).filter(([, n]) => n)
          .sort((a, b) => (b[2] - a[2]) || (b[1] - a[1]));
        [...similar.map(([p, n]) => [p, n, true]), ...others.map(([p, n]) => [p, n, false])]
          .slice(0, { l: 10, r: 10, t: 2, b: 2, tl: 3, bl: 3, tr: 3, br: 3 }[spot])
          .forEach(([part, n, sim]) => list.appendChild(chip(pos, part, n, false, sim)));
        // 角は 1 行しか置けないので「…」は付けない（すべての候補は枠のその区画を押して束で見る）
        if (spot.length > 1) return;
        const more = Object.assign(document.createElement('button'), { type: 'button', className: 'side-more', textContent: '…' });
        more.title = `${slotTitle(pos)}の候補をすべて見る`;
        more.onclick = () => openPalette(pos, true);
        list.appendChild(more);
      });
      Object.values(lists).forEach(l => el('pboxSides').appendChild(l));
      document.querySelectorAll('.pbox-btn').forEach(b => {
        const p = b.dataset.pos;
        b.textContent = slots[p] ? `${SLOT_LABEL[p]}：${slotGlyph(p, slots[p])}` : SLOT_LABEL[p];
        b.setAttribute('aria-pressed', !!slots[p]);
      });
    }
    function wirePbox() {
      const hit = el('pboxHit'), frame = el('pboxFrame');
      const zoneAt = e => {
        // 枠線のぶんを除いた内側を 176px に合わせる
        const r = frame.getBoundingClientRect();
        const x = (e.clientX - r.left - frame.clientLeft) * BOX.size / frame.clientWidth;
        const y = (e.clientY - r.top - frame.clientTop) * BOX.size / frame.clientHeight;
        return nestMode && nestSteps.length ? nestZone(x, y) : boxZone(x, y, enclosure());
      };
      hit.addEventListener('pointermove', e => {
        if (e.pointerType === 'touch') return;
        const z = zoneAt(e);
        if (z !== previewPos) preview(z);
      });
      hit.addEventListener('pointerleave', () => preview(palettePos));
      hit.addEventListener('click', e => { const z = zoneAt(e); if (z) openPalette(z, e.pointerType !== 'touch'); });
      el('pboxKeys').addEventListener('focusin', e => preview(e.target.dataset.pos));
      el('pboxKeys').addEventListener('focusout', () => preview(palettePos));
      el('pboxKeys').addEventListener('click', e => {
        // 本物のクリックは hit 側で受ける。ここに来るのはキーボードの Enter / Space だけ
        if (e.detail === 0 && e.target.dataset.pos) openPalette(e.target.dataset.pos, true);
        e.stopPropagation();
      });
      el('pboxKeys').addEventListener('keydown', e => {
        const arrow = { ArrowLeft: 'へん', ArrowRight: 'つくり', ArrowUp: 'かんむり', ArrowDown: 'あし' }[e.key];
        if (arrow) { e.preventDefault(); openPalette(arrow, true); }
        // 入れ子では位置ごとの部品を持たないので、最後に足した段を外す
        if ((e.key === 'Delete' || e.key === 'Backspace') && e.target.dataset.pos) {
          if (nestMode) setNestSteps(dropStep(nestSteps, nestSteps.length - 1)); else setSlot(e.target.dataset.pos, null);
        }
      });
      document.addEventListener('pointerdown', e => {
        if (palettePos && !e.target.closest('#partPalette, #pboxHit, .pbox-btn, .cond, .side-chip')) closePalette();
      });
      document.addEventListener('keydown', e => { if (e.key === 'Escape' && palettePos) { closePalette(); e.preventDefault(); } });
    }

    /* 字の検索と部品は別の探し方で、重ねると 0 件になりやすく、いまどちらで引いているかも分からなくなる。
       部品を入れたら検索欄を空け、検索欄に打ったら部品を外す */
    const clearQuery = () => { el('mjSearch').value = ''; el('mjmapStatus').textContent = ''; };
    function setSlot(pos, part) {
      if (part == null) delete slots[pos]; else { slots[pos] = part; clearQuery(); }
      if (!enclosure()) delete slots['なかみ'];   // 囲いを外したら中身の区画ごと消える
      closePalette();
      pushNext = true;
      renderKanji();
    }
    function setNestSteps(steps) {
      if (steps.length > nestSteps.length) clearQuery();
      nestSteps = steps;
      closePalette();
      pushNext = true;
      renderKanji();
    }
    // 束やボタンで部品を選んだとき。入れ子の位置なら形に 1 段足し、ほかは位置の部品を入れ替える（同じなら外す）
    function pick(pos, part) {
      if (isNestPos(pos)) setNestSteps(withPick(pos, part));
      else setSlot(pos, slots[pos] === part ? null : part);
    }

    /* ---- 束（チップの popover） ---- */
    let paletteAll = false;
    function openPalette(pos, focus) {
      palettePos = pos;
      paletteAll = false;
      const pal = el('partPalette');
      pal.dataset.side = paletteSide(pos);
      pal.dataset.align = pos === 'たれ' ? 'top' : pos === 'にょう' ? 'bottom' : '';
      pal.setAttribute('aria-label', `${slotTitle(pos)}の部品`);
      pal.innerHTML = `
        <div class="pal-head"><b>${slotTitle(pos)}</b>
          ${danK(pos) >= 0 ? `<span class="pal-now">いま：${nestSteps[danK(pos)][1]}</span><button type="button" class="pal-clear">外す</button>`
            : isNestPos(pos) ? nestSteps.length ? holeK(pos) >= 0 ? '' : '<span class="pal-now">いまの形の外を包む</span>' : ''
            : slots[pos] ? `<span class="pal-now">いま：${slotGlyph(pos, slots[pos])}</span><button type="button" class="pal-clear">外す</button>` : ''}
          <button type="button" class="pal-close" aria-label="閉じる">×</button></div>
        <input type="text" class="pal-find" id="paletteFind" placeholder="${pos === 'ぶしゅ' ? '字・読み・番号' : '字・読み'}" aria-label="${slotTitle(pos)}の部品を字か読みで探す">
        <div class="pal-direct"></div>
        <div class="pal-chips" role="listbox" aria-label="${slotTitle(pos)}の部品"></div>
        <button type="button" class="pal-more" hidden></button>`;
      pal.hidden = false;
      pal.style.marginLeft = pal.style.marginRight = '';
      // 枠が左端にあると左に開く束（偏・垂・繞）が画面からはみ出す。はみ出すぶんだけ内側へ寄せる。
      // 左に開く束は右端を基準に置いているので、寄せるのも右側の余白で行う
      // （狭い画面の束は画面に貼り付くパネルなので寄せない）
      if (getComputedStyle(pal).position === 'absolute') {
        // 開く動きの起点（閉じた位置の 8px のずれ）を外して、開ききった位置で測る。
        // translate には動きを付けてあるので、動きも止めないと外した瞬間はまだ元の位置で測れてしまう
        pal.style.transition = 'none';
        pal.style.translate = 'none';
        const r = pal.getBoundingClientRect(), m = 8;
        pal.style.translate = '';
        void pal.offsetWidth;
        pal.style.transition = '';
        const dx = Math.max(m - r.left, 0) - Math.max(r.right - (document.documentElement.clientWidth - m), 0);
        if (dx && pal.dataset.side === 'left') pal.style.marginRight = `${-dx}px`;
        else if (dx) pal.style.marginLeft = `${dx}px`;
      }
      // 閉じた位置を一度確定させてから open を付け、開く動きを出す。requestAnimationFrame に任せると、
      // 描画が止まっている間（裏に回ったタブなど）に付かず、束が画面の外に置かれたままになる
      void pal.offsetWidth;
      pal.classList.add('open');
      pal.querySelector('.pal-close').onclick = closePalette;
      const clr = pal.querySelector('.pal-clear');
      if (clr) clr.onclick = () => danK(pos) >= 0 ? setNestSteps(dropStep(nestSteps, danK(pos))) : setSlot(pos, null);
      const find = pal.querySelector('.pal-find');
      find.addEventListener('input', fillPalette);
      find.addEventListener('keydown', e => {
        if (e.isComposing || e.key !== 'Enter') return;
        const first = pal.querySelector('.pal-direct button, .pal-chips button:not([hidden])');
        if (first && find.value.trim()) first.click();
      });
      pal.querySelector('.pal-more').onclick = () => { paletteAll = true; fillPalette(); };
      fillPalette();
      preview(pos);
      if (focus) find.focus({ preventScroll: true });
      // 冠の束は枠の上に開くので、枠が画面の上の方にあると切れる。束が収まるところまで縦にだけ送る
      // （scrollIntoView は横にも送り、旁の束で画面ごと右へ寄ってしまう）
      if (getComputedStyle(pal).position === 'absolute') {
        const r = pal.getBoundingClientRect(), top = navH() + 8, bottom = innerHeight - 8;
        if (r.top < top) window.scrollBy(0, r.top - top);
        else if (r.bottom > bottom) window.scrollBy(0, Math.min(r.bottom - bottom, r.top - top));
      }
    }
    function closePalette() {
      if (!palettePos) return;
      palettePos = null;
      const pal = el('partPalette');
      pal.classList.remove('open');
      pal.hidden = true;
      preview(null);
    }
    // 入力と件数に合わせて束の中身を組み直す。件数は束を開いたときと、一覧を描き直したときに数え直す
    function fillPalette() {
      const pos = palettePos;
      if (!pos) return;
      const pal = el('partPalette');
      const t = hira(pal.querySelector('.pal-find').value.trim().normalize('NFKC'));
      const T = conditionChars(pos, isNestPos(pos) ? [] : undefined);
      const chips = paletteChips(pos);
      const fam = new Set(Array.from(t).map(radFamily));
      const match = c => fam.has(radFamily(c.glyph)) || (c.yomi && c.yomi.includes(t)) || (pos === 'ぶしゅ' && c.part === t);
      // 件数のある部品を先に並べる（並びの中は元の順のまま）。いまの条件で 0 件の部首が先頭を埋めると、
      // 当たる部品が「ほか」の奥に隠れる。最初に見せる数は今までどおり（呼び名のある部首の数か 30）
      const counted = chips.map(c => ({ c, n: partCount(pos, c.part, T) }));
      const ordered = [...counted.filter(x => x.n), ...counted.filter(x => !x.n)];
      const baseN = chips.some(c => c.named) ? chips.filter(c => c.named).length : 30;
      const shown = t ? ordered.filter(x => match(x.c)) : paletteAll ? ordered : ordered.slice(0, baseN);
      const box = pal.querySelector('.pal-chips');
      box.innerHTML = '';
      shown.forEach(({ c, n }) => {
        const b = document.createElement('button');
        b.type = 'button';
        b.className = 'pchip' + (n ? '' : ' zero');
        b.title = `${c.yomi || c.glyph}・${n}字`;
        b.setAttribute('role', 'option');
        b.setAttribute('aria-selected', danK(pos) >= 0 ? nestSteps[danK(pos)][1] === c.part : !isNestPos(pos) && slots[pos] === c.part);
        b.innerHTML = `<span class="g">${c.glyph}</span><span class="n">${n}</span>`;
        b.onclick = () => pick(pos, c.part);   // 選択中を押したらそのまま外す
        box.appendChild(b);
      });
      const more = pal.querySelector('.pal-more');
      more.hidden = !!t || paletteAll || shown.length >= chips.length;
      more.textContent = `ほか ${chips.length - shown.length} 個`;
      // チップに無い部品も打てば引ける（倣 の旁に 放 など）。打った字のうち、チップに無い最初の 1 字を出す
      const direct = pal.querySelector('.pal-direct');
      direct.innerHTML = '';
      if (pos === 'ぶしゅ') return;
      const typed = Array.from(t).filter(ch => !/[぀-ヿ]/.test(ch));
      const c = typed.find(ch => !chips.some(x => x.glyph === ch));
      const add = (part, label) => {
        const n = partCount(pos, part, T);
        const b = document.createElement('button');
        b.type = 'button';
        b.className = 'pal-direct-btn';
        b.disabled = !n;
        b.textContent = `${label}　${n}字`;
        b.onclick = () => isNestPos(pos) ? pick(pos, part) : setSlot(pos, part);
        direct.appendChild(b);
      };
      if (c) add(c, `「${c}」で探す`);
      // 打った字と形の似た部品も出す（干 と打てば 于 も）
      if (typed[0]) similarOf(typed[0]).forEach(p => add(p, `似た部品「${p}」`));
    }

    /* ---- 条件の一覧 ----
       入っている条件をチップで並べ、件数と一緒に枠の下に置く。
       チップの × で 1 つずつ、「すべて外す」で全部を外せる。全部外したあとは少しのあいだ元に戻せる。 */
    let undoState = null, undoTimer = 0;
    function activeConditions() {
      const live = liveSlots();
      const out = [
        ...(nestMode ? nestSteps : []).map(([, part], i) => part == null ? null
          : { label: stepLabel(i), value: part, off: () => setNestSteps(dropStep(nestSteps, i)) }).filter(Boolean),
        ...Object.keys(live).map(pos => ({ label: SLOT_LABEL[pos], value: slotGlyph(pos, live[pos]), off: () => setSlot(pos, null) }))];
      const q = el('mjSearch').value.trim();
      if (q) out.push({ label: '検索', value: q, off: () => { el('mjSearch').value = ''; pushNext = true; runSearch(); } });
      if (el('onlyJinmei').checked) out.push({ label: '人名用漢字だけ', value: '', off: () => { el('onlyJinmei').checked = false; pushNext = true; runSearch(); } });
      if (el('onlyShrink').checked) out.push({ label: '縮退があるものだけ', value: '', off: () => { el('onlyShrink').checked = false; pushNext = true; runSearch(); } });
      if (kuValue()) out.push({ label: '区', value: el('kuFilter').selectedOptions[0]?.textContent || kuValue(), off: () => { el('kuFilter').value = ''; pushNext = true; runSearch(); } });
      return out;
    }
    function renderCondBar(total) {
      const bar = el('condBar');
      bar.innerHTML = '';
      const add = (tag, cls, text) => bar.appendChild(Object.assign(document.createElement(tag), { className: cls, textContent: text }));
      const conds = activeConditions();
      conds.forEach(c => {
        const b = document.createElement('button');
        b.type = 'button';
        b.className = 'cond';
        b.innerHTML = `${c.label}${c.value ? ` <b></b>` : ''} <span aria-hidden="true">×</span>`;
        if (c.value) b.querySelector('b').textContent = c.value;
        b.setAttribute('aria-label', `${c.label} ${c.value} を外す`);
        b.onclick = c.off;
        bar.appendChild(b);
      });
      add('span', 'n', `${total.toLocaleString()}字`);
      const note = gaijiState === 'building' ? '外字を索引中' : gaijiState === 'old' ? '外字は部品で引けません（mjmap.json が古い）' : '';
      // 索引中は部首検索の索引の話（組立検索は外字も初めから照合する）。古い mjmap はどちらも外字の IDS を持たない
      if (note && (Object.keys(liveSlots()).length || nestMode && nestSteps.length && gaijiState === 'old')) add('span', 'note', note);
      // すべて外す・元に戻すは、操作の起点の枠のすぐ下に置く（右の列だと枠から遠い）
      const clr = el('pboxClear');
      clr.innerHTML = '';
      const put = (tag, cls, text) => clr.appendChild(Object.assign(document.createElement(tag), { className: cls, textContent: text }));
      if (conds.length) {
        const b = put('button', 'cond-clear', 'すべて外す');
        b.type = 'button';
        b.onclick = clearKanjiSearch;
      } else if (undoState) {
        // 「元に戻す」は「すべて外す」と同じ位置に出す。押した直後にカーソルの下にあるように
        const b = put('button', 'cond-clear', '元に戻す');
        b.type = 'button';
        b.onclick = undoClear;
        put('span', 'note', 'すべて外しました');
      }
    }

    /* 人名用漢字・縮退ありのスイッチに、入れたら何字に絞られるかを出す（入っているときは今の字数）。
       いまの一覧の並びから数えるので、検索・区・枠の条件もそのまま効いた数になる。
       縮退ありは外字を一覧から外す（外字は縮退先を持たない）ので、外字の札は数えない */
    function countSwitches(total) {
      const base = it => Array.from(it.char)[0];
      const jn = el('onlyJinmei').checked ? total : listOrder.filter(it => JINMEI_CHARS.has(base(it))).length;
      const sh = el('onlyShrink').checked ? total : listOrder.filter(it => !it.mj && shrinkChars.has(base(it))).length;
      el('jinmeiN').textContent = `${jn.toLocaleString()}字`;
      el('shrinkN').textContent = mjmap ? `${sh.toLocaleString()}字` : '';
    }

    /* 0 件のとき、条件を 1 つ外すと何字になるかを並べる（枠の部品と人名用漢字で数える）。 */
    function zeroHtml() {
      // 入れ子の段は、その段を外して組み直したときの字数
      const nestTips = (nestMode ? nestSteps : []).map(([, part], i) => {
        if (part == null) return '';
        const T = conditionChars(null, dropStep(nestSteps, i));
        return `<button type="button" class="cond" data-step="${i}">${stepLabel(i)} <b>${part}</b> を外すと ${T ? T.size.toLocaleString() : 'すべての'}字</button>`;
      });
      const tips = Object.keys(liveSlots()).flatMap(pos => {
        const T = conditionChars(pos);
        // 似た部品に替えると当たるなら、外すより先にそれを出す（干 を 于 にすると 宇 が出る）
        const sim = similarOf(slots[pos]).map(p => [p, countIn(T, slotChars(pos, p))]).filter(([, n]) => n)
          .map(([p, n]) => `<button type="button" class="cond" data-pos="${pos}" data-to="${p}">${SLOT_LABEL[pos]} <b>${slots[pos]}</b> を <b>${p}</b> にすると ${n.toLocaleString()}字</button>`);
        return [...sim, `<button type="button" class="cond" data-off="${pos}">${SLOT_LABEL[pos]} <b>${slotGlyph(pos, slots[pos])}</b> を外すと ${T ? T.size.toLocaleString() : 'すべての'}字</button>`];
      });
      tips.unshift(...nestTips);
      return '<div class="empty-msg">該当する漢字が見つかりませんでした。'
        + (tips.length ? `<div class="zero-tips">${tips.join('')}</div>` : '') + '</div>';
    }

    /* 字の部品を条件に入れる操作（右クリックのメニューと、カードの「構成」のボタン）。部首検索ではその位置の部品にする。
       組立検索では、一番外のその側が空いていれば埋め、空いていなければ外を包む（枠の環を押したのと同じ）。
       中身は囲いの中が空いているときだけ入れられる。入れられないときは null */
    function partAction(pos, part) {
      if (!isNestPos(pos)) return () => setSlot(pos, part);
      if (pos === 'なかみ') {
        const k = nestHoles(nestNow()).findIndex(h => h.role === 'なかみ');
        return k >= 0 ? () => pick('あな' + k, part) : null;
      }
      return NEST_OP[pos] ? () => pick(ringFills()[pos] || pos, part) : null;
    }

    /* 字から条件へ（query by example）: カードを押した字の直下の部品をボタンで並べ、押すとその位置に入れる。 */
    let partsChar = null;
    function showCharParts(ch) {
      const box = el('charParts');
      if (!box) return;
      partsChar = ch;
      box.innerHTML = '';
      if (!ch) { box.hidden = true; return; }
      const base = Array.from(ch)[0];
      const rad = dictRadicalOf(base);
      const parts = [...topParts(base, lookupIds), ...(rad ? [['ぶしゅ', rad]] : [])];
      box.hidden = false;
      box.appendChild(document.createTextNode(`「${base}」の構成: `));
      if (!parts.length) { box.appendChild(document.createTextNode('部品なし')); return; }
      parts.forEach(([pos, part]) => {
        const b = document.createElement('button');
        b.type = 'button';
        b.textContent = pos === 'ぶしゅ' ? radicalLabel(base, part) : `${SLOT_LABEL[pos]} ${slotGlyph(pos, part)}`;
        b.setAttribute('aria-pressed', !isNestPos(pos) && slots[pos] === part);
        // 部首検索では押し直すと外す（入っている部品は押した状態で見せている）
        const act = isNestPos(pos) ? partAction(pos, part) : () => pick(pos, part);
        b.disabled = !act;
        b.onclick = act;
        box.appendChild(b);
      });
    }

    /* 辞書の部首の表示。「火」とだけ出すと火偏と読めてしまうが、火部には 灬（れっか）の字も入る
       （燕 は火部だが、火は脚の 灬）。部首名に「部」を付け、その字のどの位置にどの字形で入っているかを添える */
    function radicalLabel(base, rad) {
      const g = slotGlyph('ぶしゅ', rad);
      const forms = partForms(g);
      const r = partsOf(base) || {};
      const pos = ['へん', 'つくり', 'かんむり', 'あし', 'たれ', 'にょう', 'かまえ', 'なかみ', 'なし'].find(p => r[p] && forms.some(f => r[p].has(f)));
      const where = pos ? `（${SLOT_LABEL[pos]} ${forms.find(f => r[pos].has(f))}）` : '';
      return `辞書の部首 ${g}部${where}`;
    }

    const hira = s => s.replace(/[ァ-ヶ]/g, c => String.fromCharCode(c.charCodeAt(0) - 0x60));
    const radFamily = c => { c = c.normalize('NFKC'); return RADICAL_FAMILY[c] || c; };

    function clearKanjiSearch() {
      undoState = readState();
      clearTimeout(undoTimer);
      undoTimer = setTimeout(() => { undoState = null; renderCondBar(listOrder.length); }, 8000);
      slots = {};
      nestSteps = [];
      closePalette();
      el('onlyJinmei').checked = false;
      el('onlyShrink').checked = false;
      el('kuFilter').value = '';
      el('mjSearch').value = '';
      el('mjmapStatus').textContent = '';
      partsChar = null;
      pushNext = true;
      renderKanji();
    }
    function undoClear() {
      if (!undoState) return;
      writeState(undoState);
      undoState = null;
      pushNext = true;
      runSearch();
    }

    /* ---- 条件を URL に持つ ----
       リロードしても、URL を渡しても、ブラウザの「戻る」でも同じ条件に戻れるようにする。
       部品や絞り込みを変えたときは履歴を積み、検索欄の打鍵では積まずに置き換える。 */
    let pushNext = false;
    function readState() {
      return { slots: { ...slots }, nest: nestMode, steps: nestSteps.map(st => [...st]), q: el('mjSearch').value.trim(), jinmei: el('onlyJinmei').checked,
               shrink: el('onlyShrink').checked, ku: kuValue() };
    }
    function writeState(st) {
      slots = { ...st.slots };
      nestMode = !!st.nest;
      nestSteps = st.steps || [];
      syncMode();
      el('mjSearch').value = st.q || '';
      el('onlyJinmei').checked = !!st.jinmei;
      el('onlyShrink').checked = !!st.shrink;
      el('kuFilter').value = st.ku || '';
      if (!el('kuFilter').value) el('kuFilter').value = ''; // 外字のブロックは mjmap を読むまで選択肢に無い
    }
    function stateHash() {
      const st = readState(), p = new URLSearchParams();
      Object.keys(st.slots).forEach(pos => p.set(pos, st.slots[pos]));
      if (st.nest !== nestByDefault(st.slots)) p.set('nest', st.nest ? '1' : '0');   // 読み手の推し量りと違うときだけ書く
      // 段の順が形を決めるので並べたまま持つ。穴埋めは経路の数字を、穴に戻した段は位置だけを書く
      st.steps.forEach(([pos, part, path]) => p.append('n', pos === 'あな' ? `あな${path.join('')}${part}` : pos + (part || '')));
      if (st.q) p.set('q', st.q);
      if (st.jinmei) p.set('jinmei', '1');
      if (st.shrink) p.set('shrink', '1');
      if (st.ku) p.set('ku', st.ku);
      const h = p.toString();
      return h ? '#' + h : '';
    }
    // nest の無い URL のモード。入れ子を既定にする前の URL は、位置に部品が入っていればラフのもの
    const nestByDefault = sl => !Object.keys(sl).some(k => !NEST_FREE.includes(k));
    function hashState() {
      const p = new URLSearchParams(location.hash.slice(1)), st = { slots: {} };
      p.forEach((v, k) => { if (SLOT_LABEL[k]) st.slots[k] = v; });
      st.nest = p.has('nest') ? p.get('nest') !== '0' : nestByDefault(st.slots);
      st.steps = p.getAll('n').map(v => {
        const h = v.match(/^あな([01]+)(.+)$/u);
        if (h) return ['あな', h[2], Array.from(h[1], Number)];
        const pos = Object.keys(NEST_OP).find(k => v.startsWith(k));
        return pos ? [pos, v.slice(pos.length) || null] : null;
      }).filter(Boolean);
      st.q = p.get('q') || '';
      st.jinmei = p.get('jinmei') === '1';
      st.shrink = p.get('shrink') === '1';
      st.ku = p.get('ku') || '';
      if (!enclosureOf(st.slots)) delete st.slots['なかみ'];
      return st;
    }
    function commitHash() {
      const h = stateHash();
      if (h !== location.hash && !(h === '' && location.hash === '')) {
        history[pushNext ? 'pushState' : 'replaceState'](null, '', h || location.pathname + location.search);
      }
      pushNext = false;
    }
    window.addEventListener('popstate', () => { writeState(hashState()); closePalette(); runSearch(); });

    function renderKanji() {
      const container = document.getElementById('kanjiContainer');
      container.innerHTML = '';
      listOrder = []; sections = [];
      directHits = new Set(); shrinkPulled = new Set();

      // 枠に入れた部品は AND で重ねる（人名用漢字や検索と同じ畳み方）。null = すべて
      let targetChars = frameChars();
      // 当たった字の縮退先も一覧に入れる。あめかんむりで引くと 霸 は出るが 覇 は出ないので、
      // 霸 の字形(MJ027866)が縮退する先の 覇 の群がツリーに出てこない。検索と同じ扱いにする
      if (targetChars) targetChars = withShrinkTargets(targetChars);
      // 人名用漢字は第1〜3水準に散っているので、部首と同じ絞り込みとして重ねる
      if (el('onlyJinmei').checked) {
        targetChars = targetChars ? new Set([...targetChars].filter(c => JINMEI_CHARS.has(c))) : new Set(JINMEI_CHARS);
      }
      // いま選んでいる根拠で縮退が1本も無い字を落とす。根拠を絞るほどここも絞れる
      if (el('onlyShrink').checked) {
        targetChars = targetChars ? new Set([...targetChars].filter(c => shrinkChars.has(c))) : new Set(shrinkChars);
      }

      // 区の絞り込みは「面区」か「外字のブロック」のどちらか。検索欄は字の絞り込みとして別に効かせる
      const kuOk = kuMatcher();
      const blk = blockValue();
      const q = document.getElementById('mjSearch').value.trim();
      if (q) {
        const only = withShrinkTargets(resolveQuery(q));
        targetChars = targetChars ? new Set([...targetChars].filter(c => only.has(c))) : only;
      }

      let total = 0;
      // 記号は水準の並びの外なので先頭に置く。第4水準と外字の間だと 44,349枚 に埋もれる
      if (!kuOk && !blk) total += renderSymbols(container, targetChars);

      if (!blk) [1, 2, 3, 4].forEach(level => {
        const chars = allKanjiList[level];
        const kus = kuByLevel[level];
        const items = []; // [{char, ku}] フィルタを適用した並び（区点の昇順を維持）
        for (let i = 0; i < chars.length; i++) {
          const char = chars[i];
          if (targetChars !== null && !targetChars.has(char)) continue;
          if (kuOk && !kuOk(level, kus[i])) continue;
          items.push({ char, ku: kus[i] });
        }
        if (items.length === 0) return;
        total += items.length;

        // フィルタの有無に関わらず1本のグリッドで描画。区が変わった最初のカードだけ溝に区番号を出す。
        // 札の有無は窓を組み直すたびに要るので、描画結果ではなく listOrder 側に持たせる。
        const base = listOrder.length;
        let prevKu = null;
        items.forEach(({ char, ku }) => {
          listOrder.push({ char, level, ku, tag: ku !== prevKu ? `区${ku}` : '' });
          prevKu = ku;
        });
        addSection(container, `lvl${level}`, `第${level}水準`, items.length, base);
      });

      // 外字は面区点を持たないので、面区点で絞っているときは出さない。
      // 縮退先も持たないので、「縮退があるものだけ」のときも出さない。基底の字が縮退に関わっている
      // だけで通すと、俗字だけ ON でも外字が100枚ついてきて、縮退のある字の数に見えてしまう
      if (!kuOk && !el('onlyShrink').checked) total += renderGaiji(container, targetChars, blk);

      if (total === 0) {
        container.innerHTML = zeroHtml();
        container.querySelectorAll('[data-off]').forEach(b => { b.onclick = () => setSlot(b.dataset.off, null); });
        container.querySelectorAll('[data-to]').forEach(b => { b.onclick = () => setSlot(b.dataset.pos, b.dataset.to); });
        container.querySelectorAll('[data-step]').forEach(b => { b.onclick = () => setNestSteps(dropStep(nestSteps, +b.dataset.step)); });
        sections = [];
      }
      relayout();        // 高さを入れて位置を測り直し、見えている窓だけ描く
      buildSectionJump();
      rebuildTree();
      drawPbox();
      renderCondBar(total);
      countSwitches(total);
      fillPalette();
      showCharParts(partsChar);
      commitHash();
    }

    /* ---- 検索で当たった字の縮退先も一覧に入れる ----
       旧字体だけを出すと、その字の群は縮退先を1行にまとめて「国—國—國」と描く。
       これは1つのMJ字形が2つの面区点へ縮退していることの正しい表示だが、
       縮退の向き（國 が 国 へ潰れる）は読み取れない。
       終着点の 国 を一覧に入れれば 国 の群が出て、國 はその枝として下がる。
       その字を字形として持つMJ（基底が一致するMJ）だけを辿るので、
       たまたま同じ縮退先を持つだけの字までは引き込まない。 */
    let directHits = new Set();   // フィルタに直接当たった字
    let shrinkPulled = new Set(); // 縮退先として引き込んだだけの字
    function withShrinkTargets(chars) {
      if (!mjmap) return chars;
      const out = new Set(chars);
      chars.forEach(ch => (mjByChar.get(ch) || []).forEach(mi => {
        if (mjBase[mi] !== ch) return;
        (candByMj.get(mi) || []).forEach(([ji]) => out.add(jisCh[ji]));
      }));
      // 直接当たった字と、連れてきただけの字を分けて控える。ツリーで出す行を変えるため
      chars.forEach(c => { directHits.add(c); shrinkPulled.delete(c); });
      out.forEach(c => { if (!directHits.has(c)) shrinkPulled.add(c); });
      return out;
    }

    /* ---- 見出しへ飛ぶチップ ----
       一覧は5万枚を超えるので、スクロールだけでは記号も外字も辿り着けない。
       カードは見えている行しか実体化しないので、件数はセクションの記述子から出す。 */
    function buildSectionJump() {
      const bar = document.getElementById('sectionJump');
      bar.innerHTML = '';
      // 該当0件でも札を1枚置いて行の高さを保つ。空にすると行が潰れ、下の一覧ごとせり上がる
      if (!sections.length) {
        const b = document.createElement('button');
        b.className = 'jump-chip';
        b.disabled = true;
        b.textContent = '該当なし';
        bar.appendChild(b);
        return;
      }
      sections.forEach(s => {
        const b = document.createElement('button');
        b.className = 'jump-chip';
        b.style.color = LEVEL_COLOR[s.lv] || LEVEL_COLOR[5];
        b.innerHTML = `${s.label}<span class="n">${s.n.toLocaleString()}</span>`;
        b.onclick = () => scrollToSection(s);
        bar.appendChild(b);
      });
    }

    // 見出しは sticky で上端に貼り付くので位置の基準にならない。グリッドの位置から測り、
    // 見出しの高さぶん手前に止める。見出しは数個しか無いので、その高さだけは実測でよい。
    function scrollToSection(s) {
      driver = 'list';
      listScrollTo(s.top - (s.sep.offsetHeight + 8));
      if (!document.body.classList.contains('tree-on')) return;
      // 見出しの手前に止めるので、スクロール位置から引くと1つ前のセクションの末尾に当たり、
      // ツリーが送りきれない。ツリーはそのセクションの先頭のカードに直接合わせる。
      // 記号はツリーの行を持たないので（base<0）、そこは位置から引くしかない。
      if (s.base < 0) { syncTree(); return; }
      curAnchor = -1;
      alignTree(s.base);
    }

    /* カードは1枚ずつ createElement すると効くので、HTMLを組んでグリッド単位で流し込む。
       クリックは #kanjiContainer の委譲で受けるので、カードごとのハンドラも張らない。 */
    function cardHtml(cls, char, title, extra, style) {
      return `<div class="card ${cls}" style="${style}" title="${title}" data-char="${char}">`
        + `${extra || ""}${tokDot(Array.from(char)[0])}<span class="char-main">${char}</span></div>`;
    }
    /* 一覧の i 番目のカードを、そのセクションの j 枚目の位置に組む。
       窓に入るたびに組み直されるので、札も説明も listOrder の中身だけから作れるようにしてある。 */
    function listCardHtml(i, j) {
      const it = listOrder[i];
      const title = it.mj
        ? `「${it.char}」 ${it.mj} U+${it.char.codePointAt(0).toString(16).toUpperCase()} ${it.blk}`
        : `「${it.char}」 ${charJis.get(it.char) || (it.ku == null ? `第${it.level}水準` : `第${it.level}水準 区${it.ku}`)}`;
      // 光らせる1枚はDOMではなく添字で持っているので（flashI）、ここで着せ直す
      const hot = i === flashI;
      return cardHtml(`lvl${it.level}${hot ? " flash" : ""}`, it.char, title,
        it.tag ? `<span class="ku-tag">${it.tag}</span>` : "",
        cardPos(j) + (hot ? `;--flash:${LEVEL_COLOR[it.level] || LEVEL_COLOR[5]}` : ""));
    }

    // --- 変体仮名モードのUI制御（あ行/か行…ごとにセパレートし、ひらがな単位で改行して常時全件表示） ---
    function renderHentaigana() {
      const container = document.getElementById('hentaiganaContainer');
      container.innerHTML = '';

      let total = 0;
      const jumps = []; // 移動チップの元。見出しと、そこにぶら下がる枚数
      // 繰り返し記号・合略仮名。五十音の行には属さないので先頭に1行ずつ置く
      [["繰り返し記号", KANA_REPEATS], ["合略仮名", KANA_LIGATURES]].forEach(([label, list]) => {
        const sep = document.createElement('div');
        sep.className = 'level-separator';
        sep.innerHTML = `<span>${label}</span>`;
        container.appendChild(sep);
        const grid = document.createElement('div');
        grid.className = 'hentai-grid';
        list.forEach(([ch, uni, name]) => {
          const card = document.createElement('div');
          card.className = ch.length > 1 ? 'card kana-vert' : 'card'; // 2字=くの字点は縦に組む
          card.innerHTML = `
              <span class="char-main">${ch}</span>
              <div class="hentai-meta">
                <span>${uni}</span>
                <span>${name}</span>
              </div>
            `;
          card.onclick = () => copyText(ch, `「${ch}」`);
          grid.appendChild(card);
        });
        container.appendChild(grid);
        total += list.length;
        jumps.push({ sep, label, n: list.length });
      });

      GOJUON_ROWS.forEach(row => {
        const baseItems = row.bases.map(base => HENTAIGANA_DATA.filter(d => d.base === base));
        const rowTotal = baseItems.reduce((sum, items) => sum + items.length, 0);
        if (rowTotal === 0) return;
        total += rowTotal;

        const sep = document.createElement('div');
        sep.className = 'level-separator';
        sep.innerHTML = `<span>${row.label}</span>`;
        container.appendChild(sep);
        jumps.push({ sep, label: row.label, n: rowTotal });

        row.bases.forEach((base, i) => {
          const items = baseItems[i];
          if (items.length === 0) return;

          const line = document.createElement('div');
          line.className = 'kana-line';

          const label = document.createElement('div');
          label.className = 'kana-label';
          label.innerText = base;
          line.appendChild(label);

          const grid = document.createElement('div');
          grid.className = 'hentai-grid';
          items.forEach(item => {
            const card = document.createElement('div');
            card.className = 'card';
            card.innerHTML = `
              <span class="char-main">${item.char}</span>
              <div class="hentai-meta">
                <span>字母: ${item.jibo}</span>
              </div>
            `;
            card.onclick = () => copyText(item.char, `変体仮名「${item.char}」`);
            grid.appendChild(card);
          });
          line.appendChild(grid);
          container.appendChild(line);
        });
      });

      if (total === 0) container.innerHTML = '<div class="empty-msg">該当する変体仮名が見つかりませんでした。</div>';
      buildKanaJump(jumps);
    }

    /* ---- 見出しへ飛ぶチップ（変体仮名モード） ----
       五十音が10段あり、下の行はスクロールしないと辿り着けないので漢字モードと同じ札を出す。
       一覧は漢字モードのペインと同じく画面に貼り付けてあるので、送るのはその中だけ。
       見出しは sticky で上端に貼り付き位置の基準にならないため、次に来る中身から測る。 */
    function buildKanaJump(jumps) {
      const bar = document.getElementById('kanaJump');
      bar.innerHTML = '';
      jumps.forEach(j => {
        const b = document.createElement('button');
        b.className = 'jump-chip';
        b.innerHTML = `${j.label}<span class="n">${j.n.toLocaleString()}</span>`;
        b.onclick = () => {
          const pane = document.getElementById('hentaiganaContainer');
          pane.scrollTop = paneTop(j.sep.nextElementSibling || j.sep, pane) - (j.sep.offsetHeight + 8);
        };
        bar.appendChild(b);
      });
    }

    /* =====================================================================
       縮退・包摂ツリー（mjmap.json）
       tools/build-mjmap.py が MJ文字情報一覧表(xlsx=字形/IVS) と
       MJ縮退マップ(json=縮退グラフ) を統合した mjmap.json を読む。
       ツリーは「1行 = 1 MJ字形」。行内のノードはその字自身の水準の列に置き、
       左ほど縮退の終着点(第1水準)、右ほど源流(MJ)になる。
       ===================================================================== */
    const LEVEL_COLOR = { 1: "#3498db", 2: "#9b59b6", 3: "#e67e22", 4: "#e74c3c", 5: "#7f8c8d" };
    const COL_W = 90, ROW_H = 34, SUB_H = 34;
    const COL_LABEL = ["第1水準", "第2水準", "第3水準", "第4水準", "MJ"];

    let mjmap = null;
    let ipamjInstalled = false; // IPAmj明朝がこの環境に入っているか（検出結果）
    let useIPAmj = false;       // 字形の描画にIPAmj明朝を使うか（バッジで切り替える）
    const charLevel = new Map();  // 文字 -> 水準。一覧の生成結果がそのまま正解なので流用する
    const mjByChar = new Map();   // 文字 -> [MJ index]（その字を実装する／その字へ縮退する）
    const shrinkChars = new Set();// いま選んでいる根拠で縮退に関わる字（ツリーに縮退の行が出る字）
    const candByMj = new Map();   // MJ index -> [面区点の添字]
    const mjIndex = new Map();    // "MJ000089" -> index
    const jisChar = new Map();    // "1-18-81" -> "会"
    const repOf = new Map();      // MJ index -> その面区点のJIS例示字形になっている面区点のindex（bit0）
    const charJis = new Map();    // "会" -> "1-18-81"
    let jisCh = [];               // 面区点の添字 -> 文字
    let mjBase = [];              // MJ index -> 基底の1文字。ツリーの並べ替えで何度も引くので先に作っておく

    // 一覧の描画順。ツリーの行順と縦スクロール同期の基準になる
    let listOrder = [], sections = [];
    let cols = 1, pitch = 0;      // 一覧の列数とカード1行の送り。実測するのはこの2つだけ
    let treeRows = [], treeGroups = [], firstRowOf = [], drawnAt = new Map();

    const el = id => document.getElementById(id);
    // tokenizer.json の語彙にある字に付ける丸。丸そのものに説明を持たせるので実体の span で出す
    const tokDot = ch => TOK.has(ch) ? '<span class="tok-dot" title="tokenizer.json の語彙にある字"></span>' : '';
    const push = (map, k, v) => { const a = map.get(k); a ? a.push(v) : map.set(k, [v]); };
    const mjName = num => "MJ" + String(num).padStart(6, "0");
    /* 縮退の根拠。mjmap.json の縮退先は1エッジにこのビットを複数立てて持つ（meta.bits に同じ並び）。
       bit0 はJIS例示字形（下の BIT_REP）で根拠の選択の対象外なので、SRC は bit1 から始まる。
       強い順に並べてあり、線種は立っている根拠のうち一番強いもので決める。
       tier 0=実線（規格）、1=破線（法令・告示）、2=点線（辞書・類推）。新旧字体は橙の実線。
       常用漢字表の新旧字体は戸籍法通達の部分集合ではない（包摂や582号だけで繋がる組が7本ある）
       ので独立したビットを持ち、強さの順どおり包摂の次に置いてある。
       並びは強さの順で、ビットの番号（b）は mjmap.json の meta.bits の並び。親字の親字は後から足した
       ビットなので番号は末尾だが、強さは親字・正字の次に置く。古い mjmap.json にはこのビットが無く、
       遠い親字も親字・正字に入ったまま読める。 */
    const SRC = [
      { id: "srcJis",    b: 1,  label: "包摂・統合", tier: 0, on: true,  title: "JIS包摂規準・UCS統合規則。規格の上で同じ文字とされる関係（14,515本）" },
      { id: "srcKyuu",   b: 2,  label: "新旧字体",   tier: 0, on: true, kj: true, title: "常用漢字表（平成22年内閣告示第2号）のいわゆる康熙字典体。橙の実線で描く（364組）" },
      { id: "srcSeiji",  b: 3,  label: "親字・正字", tier: 1, on: false, group: "戸籍", title: "法務省戸籍法関連通達・通知／戸籍統一文字情報 親字・正字。その字形から親字をたどって一番近くで届く JIS の字（14,908本）。それより先（2段以上）で届く字も点線で出す（3,132本）" },
      // 親字・正字の縮退先のうち、一番近い段より遠いもの。MJ000050 は 1 段で 侮(FA30)、2 段で 侮(4FAE)。
      // 遠い方を同じ根拠にすると両方へ直接縮退するように見えるので、ビットは分けて点線で描く。
      // 入り切りは親字・正字のチップに畳む（2 段先にも繋がっていることは、点線と根拠の説明で分かる）
      { id: "srcSeiji2", b: 11, label: "親字の親字", tier: 2, on: false, group: "戸籍", chip: "srcSeiji", title: "戸籍統一文字情報 親字・正字のうち、一番近い親字よりさらに先（2段以上）で届く JIS の字（3,132本）" },
      { id: "srcZoku",   b: 4,  label: "俗字",       tier: 1, on: false, group: "戸籍", title: "民一2842号通達別表 誤字俗字・正字一覧表のうち俗字（233本）と、同日の民二5202号通知別表 正字・俗字等対照表（138本）。漢和辞典に俗字として載る同字の異体で、戸籍にそのまま残せる" },
      // 5202号の対照表は同日の依命通知の別表で、138本のうち120本は上の俗字と重なる。俗字のチップに畳む
      { id: "srcZokuji", b: 5,  label: "正字・俗字", tier: 1, on: false, group: "戸籍", chip: "srcZoku", title: "法務省戸籍法関連通達・通知／民二5202号通知別表 正字・俗字等対照表（138本）" },
      { id: "srcGoji",   b: 6,  label: "誤字",       tier: 1, on: false, group: "戸籍", title: "民一2842号通達別表 誤字俗字・正字一覧表のうち無印＝誤字。辞書に無い誤った字体で、職権で正字に訂正される（618本）" },
      { id: "srcBetsu",  b: 7,  label: "別字",       tier: 1, on: false, group: "戸籍", title: "民一2842号通達別表 誤字俗字・正字一覧表のうち別字。正字とは別の字だが混用されているもので、申出で正字に訂正できる（150本）" },
      { id: "src582",    b: 8,  label: "告示582号",  tier: 1, on: false, title: "法務省告示582号別表第四。在留カード等に係る漢字氏名の表記（12,568本）" },
      // 辞書・類推は縮退の根拠としては弱すぎて常用しないので、データには持つがチップは出さない
      { id: "srcDict",   b: 9,  label: "辞書",       tier: 2, on: false, hidden: true, title: "辞書類等による関連字（15,958本）" },
      { id: "srcGuess",  b: 10, label: "読み・字形", tier: 2, on: false, hidden: true, title: "読み・字形による類推（413本）" },
    ];
    SRC.forEach(s => s.bit = 1 << s.b);
    const BIT_REP = 1;
    const BIT_KYUUJITAI = SRC.find(s => s.kj).bit;
    const srcMask = () => SRC.reduce((m, s) => m | (s.on ? s.bit : 0), 0);
    // 立っている根拠のうち一番強いものの段。SRC は強い順なので先に見つかったものが答え
    const tierOf = bits => (SRC.find(s => bits & s.bit) || { tier: 2 }).tier;

    // ---- ツリーの開閉だけ localStorage に覚える（読めない環境では黙って既定に倒す） ----
    const TREE_PREF = "unicopy.treeOpen";
    const treeWasOpen = () => { try { return localStorage.getItem(TREE_PREF) === "1"; } catch { return false; } };
    const saveTreeOpen = on => { try { localStorage.setItem(TREE_PREF, on ? "1" : "0"); } catch { } };

    // http(s) で配信されているか。file:// で開いたときだけ IndexedDB を使う
    const SERVED = /^https?:$/.test(location.protocol);
    // ---- IndexedDB（mjmap.json は 4〜5MB あり localStorage には入らない。file:// 用） ----
    function idb(mode, fn) {
      return new Promise((res, rej) => {
        const rq = indexedDB.open("unicopy", 1);
        rq.onupgradeneeded = () => rq.result.createObjectStore("kv");
        rq.onerror = () => rej(rq.error);
        rq.onsuccess = () => {
          const tx = rq.result.transaction("kv", mode);
          const r = fn(tx.objectStore("kv"));
          tx.oncomplete = () => res(r && r.result);
          tx.onerror = () => rej(tx.error);
        };
      });
    }

    // ---- IPAmj明朝の検出（IVS付き文字を正しい字形で描けるか） ----
    function checkIPAmjFont() {
      let ok = false;
      if (document.fonts && document.fonts.check) {
        ok = document.fonts.check('16px "IPAmj明朝"') || document.fonts.check('16px "IPAmjMincho"');
      }
      if (!ok) {
        // fonts.check が当てにならない環境向け。同じ字を2種のフォントで描いて差を見る
        const cv = document.createElement("canvas");
        cv.width = cv.height = 40;
        const ctx = cv.getContext("2d", { willReadFrequently: true });
        const draw = font => {
          ctx.clearRect(0, 0, 40, 40);
          ctx.font = font; ctx.textBaseline = "top"; ctx.fillText("廝", 0, 0);
          return ctx.getImageData(0, 0, 40, 40).data.toString();
        };
        ok = draw("30px monospace") !== draw("30px 'IPAmj明朝', 'IPAmjMincho', monospace");
      }
      ipamjInstalled = ok;
      useIPAmj = ok;
      updateFontBadge();
    }

    /* バッジが示すのは「いま何のフォントでMJ字形を描いているか」。
       IPAmj明朝が入っているかどうかは検出結果として title に回す。
       検出はフォント名の問い合わせしか見ていないので外すことがあり、
       またIVSはシステムの明朝が持っていれば IPAmj明朝 なしでも描き分かる。 */
    function updateFontBadge() {
      const b = el("fontBadge");
      b.textContent = useIPAmj ? "MJ字形: IPAmj明朝" : "MJ字形: 既定の明朝";
      b.className = "font-status-btn " + (useIPAmj ? "status-active" : "status-inactive");
      b.title = (ipamjInstalled ? "IPAmj明朝を検出しました。" : "IPAmj明朝は検出できませんでした（入っていても検出を外すことがあります）。")
        + "クリックで描画に使う/使わないを切り替えます";
      document.body.classList.toggle("no-mjfont", !useIPAmj);
    }

    // ---- mjmap.json の取り込み ----
    const DATA_SOURCE = { idb: "保存済みデータ", fetch: "mjmap.json", file: "選択したファイル" };
    const setDataState = (ready, text) => {
      el("dataBtn").classList.toggle("ready", ready);
      el("dataBtn").title = text;
    };
    function loadMjmap(text, source) {
      mjmap = JSON.parse(text);
      mjByChar.clear(); candByMj.clear(); mjIndex.clear(); jisChar.clear();

      repOf.clear();
      jisCh = mjmap.jis.map(j => j[1]);
      mjBase = mjmap.mj.map(m => m[1] && String.fromCodePoint(m[1].codePointAt(0)));
      mjmap.mj.forEach((m, i) => {
        mjIndex.set(mjName(m[0]), i);
        m[2].forEach(([ji, bits]) => { if (bits & BIT_REP) repOf.set(i, ji); });
      });
      mjmap.jis.forEach((j, k) => {
        jisChar.set(j[0], jisCh[k]);
        if (!charJis.has(jisCh[k])) charJis.set(jisCh[k], j[0]);
      });
      buildEdges();
      indexGaiji(); // 外字の基底字（mjBase）が揃ってから組む

      setDataState(true, `読込済み（${DATA_SOURCE[source] || "不明"}）／クリックで別のファイルを読む`);
      el("mjmapStatus").textContent = "";
      el("showTree").disabled = false;
      el("mjSearch").disabled = false;
      renderKanji(); // MJ外字セクションが増えるので一覧ごと描き直す（末尾で rebuildTree される）
      fillGaijiBlocks();
      // URL の区が外字のブロックだったときは、選択肢がここで初めて揃う
      const ku = hashState().ku;
      if (ku && !kuValue()) { el("kuFilter").value = ku; if (kuValue()) runSearch(); }
      if (treeWasOpen()) { el("showTree").checked = true; applyView(); } // 一覧を描いてからでないと同期の基準が無い
    }

    /* 選んだ根拠でエッジを張り直す。根拠を切ると縮退先が無くなるMJは外字へ回る。
       ただし、その面区点の正字（X0213 包摂区分0 かつ「実装したUCS」あり＝bit0）への
       エッジは根拠の選択に関わらず残す。縮退マップはこれを包摂規準のエッジとして
       持っている（MJ自身の面区点は別枠では持っていない）が、中身は縮退ではなく
       「この字形がこの面区点の字である」という1:1の対応なので、包摂を外したからと
       いって消してよいものではない。消すと 亜(1-16-01) の字形 MJ006454 や
       亞(1-48-19) が丸ごと落ちて、亞→亜 の新旧字体だけが宙に浮いた1行になる。

       残すのはこの正字のエッジだけ。基底の符号位置が同じでも包摂規準が当たっているMJ
       （医+E0102=MJ007821 は規準U118で1-16-69へ、醫+E0102=MJ026548 も同じくU118）は
       字形が違うので、その面区点との関係は1:1ではなく包摂である。
       区分0は1つの面区点に複数あることがあり（10,909本／10,054面区点、785面区点が2つ以上）、
       愛(1-16-06) は MJ011751(E0102) と MJ011752(E0101) の両方が区分0だが、
       「実装したUCS」を持つ MJ011752 だけが正字として bit0 を持つ。 */
    /* 親字の親字の根拠の説明。近い親字の字（A）の正字が、その字へ親字・正字で繋がっていれば
       「A を経て」と添える（MJ000050 → 侮(FA30) → 侮(4FAE)）。途中の字が JIS に無いものは段だけ言う */
    const SEIJI = SRC.find(s => s.id === 'srcSeiji'), SEIJI2 = SRC.find(s => s.id === 'srcSeiji2');
    let repByJi = new Map();
    function farLabel(mi, ji, es) {
      for (const [aj, e] of es) {
        if (!(e.bits & SEIJI.bit)) continue;
        const r = repByJi.get(aj);
        const re = r == null ? null : mjmap.mj[r][2].find(([j]) => j === ji);
        // 侮(FA30) と 侮(4FAE) のように見分けにくい字もあるので、面区点も添える
        if (re && re[1] & SEIJI.bit) return `親字の親字（${jisCh[aj]} ${mjmap.jis[aj][0]} を経て）`;
      }
      return '親字の親字（2段以上）';
    }
    function buildEdges() {
      candByMj.clear(); mjByChar.clear();
      repByJi = new Map([...repOf].map(([mi, ji]) => [ji, mi]));
      shrinkChars.clear();
      const mask = srcMask();
      // MJ index -> Map(面区点の添字 -> { on: 立っている根拠のビット, bits: 元のビット, kt: 派生した新旧字体の段 })
      const edges = new Map();
      mjmap.mj.forEach((m, mi) => m[2].forEach(([ji, bits]) => {
        const on = bits & mask;   // そのエッジの根拠のうち、いま選ばれているものだけ
        if (!on && !(bits & BIT_REP)) return;
        if (!edges.has(mi)) edges.set(mi, new Map());
        edges.get(mi).set(ji, { on, bits, kt: null });
      }));
      /* 新旧字体は 邊→辺 という面区点どうしの対応で、mjmap.json では旧字体の正字（邊󠄈）から
         新字体へのエッジ1本にだけビットが立っている。他のMJは、いま選んでいる根拠で 邊 に
         届いていれば（包摂・戸籍…）、邊 の新旧字体を1段たどって 辺 へも縮退させる。
         包摂を切れば 邊󠄏(MJ026199) は 邊 に届かないので 辺 へも行かない。
         派生したエッジの段は 邊 へ届いた根拠の段。边(MJ025757) は親字で 邊 なので 辺 へも破線で、
         橙にはしない（橙は規格の段で 邊 に届いた字だけ）。 */
      if (SRC.find(s => s.kj).on) {
        const kyuuOf = new Map(); // 旧字体の面区点の添字 -> [新字体の面区点の添字]
        repOf.forEach((ji, mi) => (edges.get(mi) || new Map()).forEach((e, nj) => {
          if (e.on & BIT_KYUUJITAI) push(kyuuOf, ji, nj);
        }));
        edges.forEach(es => [...es].forEach(([ji, hop]) => (kyuuOf.get(ji) || []).forEach(nj => {
          if (!hop.on) return;
          const t = tierOf(hop.on);
          const e = es.get(nj) || es.set(nj, { on: 0, bits: 0, kt: null }).get(nj);
          if (e.kt == null || t < e.kt) { e.kt = t; e.via = jisCh[ji]; }
        })));
      }
      edges.forEach((es, mi) => {
        es.forEach(({ on, bits, kt, via }, ji) => {
          // 直接のエッジと派生した新旧字体のうち強いほうの段。正字だけのエッジ（on=0）は元のビットで
          let tier = on ? tierOf(on) : kt == null ? tierOf(bits) : 9;
          let kj = !!((on || bits) & BIT_KYUUJITAI);
          if (kt != null && kt <= tier) { tier = kt; kj = kt === 0; }
          // 線の tooltip に出す根拠。選んでいる根拠と、正字・派生した新旧字体
          const why = SRC.filter(x => on & x.bit).map(x => x === SEIJI2 ? farLabel(mi, ji, es) : x.label);
          if (bits & BIT_REP) why.unshift("JIS例示字形");
          if (kt != null && !(on & BIT_KYUUJITAI)) why.push(`新旧字体（${via} を経て）`);
          push(candByMj, mi, [ji, tier, kj, !!(bits & BIT_REP), why.join("・")]);
          push(mjByChar, jisCh[ji], mi);
        });
        /* 絞り込みの「縮退があるものだけ」で使う。いま選んでいる根拠のエッジを1本でも持つMJが
           ツリーでぶら下がる字（縮退先と、そのMJが正字になっている面区点）を数える。
           MJの基底の字は数えない。俗字だけ ON のとき 凖 のある字形が 準 へ縮退していても、
           その字形が 凖 の正字でなければ 凖 の下には何も出ないので、一覧に出しても空振りになる。 */
        if ([...es.values()].some(e => e.on || e.kt != null)) es.forEach((e, ji) => shrinkChars.add(jisCh[ji]));
      });
    }

    // 続きのグループは1つの箱にまとめて、頭に出典名を1回だけ書く。
    // 他のチップに畳んだ根拠（chip）はチップを持たず、そのチップの on/off に従う
    const noChip = s => s.hidden || s.chip;
    el("srcSwitches").innerHTML = SRC.reduce((h, s, i) => {
      if (noChip(s)) return h;
      const prev = SRC.slice(0, i).reverse().find(x => !noChip(x));
      if (s.group !== (prev ? prev.group : undefined)) {
        if (prev && prev.group) h += "</span>";
        if (s.group) h += `<span class="src-group"><span class="bar-label">${s.group}</span>`;
      }
      return h + `<label class="src-chip" title="${s.title}"><input type="checkbox" id="${s.id}"${s.on ? " checked" : ""}>${s.label}</label>`;
    }, "") + (SRC.filter(s => !noChip(s)).pop().group ? "</span>" : "");
    SRC.filter(s => !noChip(s)).forEach(s => el(s.id).addEventListener("change", e => {
      SRC.forEach(x => { if (x === s || x.chip === s.id) x.on = e.target.checked; });
      if (mjmap) { buildEdges(); renderKanji(); fillGaijiBlocks(); }
    }));

    el("mjmapInput").addEventListener("change", e => {
      const f = e.target.files[0];
      if (!f) return;
      setDataState(false, "読み込み中...");
      const r = new FileReader();
      r.onload = ev => {
        try {
          loadMjmap(ev.target.result, "file");
          // 保存するのは file:// のときだけ。http(s) では次回も同じ場所の mjmap.json を取るので残しても使わない
          if (!SERVED) idb("readwrite", s => s.put(ev.target.result, "mjmap")).catch(() => {});
        } catch (err) {
          setDataState(false, "読み込みに失敗: " + err.message);
        }
      };
      r.readAsText(f);
    });

    // 外字の区分けに使う Unicode ブロック（MJ文字集合に実際に現れるものだけ）
    const CJK_BLOCKS = [
      [0x2E80, 0x2FDF, "CJK部首"], [0x3400, 0x4DBF, "CJK拡張A"], [0x4E00, 0x9FFF, "CJK統合漢字"],
      [0xF900, 0xFAFF, "CJK互換漢字"], [0x20000, 0x2A6DF, "CJK拡張B"], [0x2A700, 0x2B73F, "CJK拡張C"],
      [0x2B740, 0x2B81F, "CJK拡張D"], [0x2B820, 0x2CEAF, "CJK拡張E"], [0x2CEB0, 0x2EBEF, "CJK拡張F"],
      [0x2EBF0, 0x2EE5D, "CJK拡張I"], [0x2F800, 0x2FA1F, "CJK互換漢字補助"],
      [0x30000, 0x3134F, "CJK拡張G"], [0x31350, 0x323AF, "CJK拡張H"],
    ];
    function cjkBlock(code) {
      const b = CJK_BLOCKS.find(([a, z]) => code >= a && code <= z);
      return b ? b[2] : "その他";
    }

    /* ---- 一覧に付ける記号セクション ----
       々〆〇〻ヶ は漢字ではない（Ideographic でない）ので水準の一覧には出ないが、
       漢字に添えて使うのでここでコピーできるようにする。 */
    function renderSymbols(container, targetChars) {
      const items = KANJI_SYMBOLS.filter(([ch]) => targetChars === null || targetChars.has(ch));
      if (!items.length) return 0;

      // 記号はツリーの行を持たない（縮退先ではなく添え字なので）ので listOrder には積まない。
      // 積まないぶん base を持たないので、セクションには -1 を渡して位置の計算から外す
      addSection(container, "lvl5 flat", "記号", items.length, -1, j => {
        const [ch, name] = items[j];
        const jis = charJis.get(ch);
        return cardHtml("lvl5", ch, `「${ch}」 ${name} ${jis ? jis + " " : ""}U+${ch.codePointAt(0).toString(16).toUpperCase()}`, "", cardPos(j));
      });
      return items.length;
    }

    /* ---- 一覧の末尾に付ける外字セクション ----
       縮退先が1つも定義されていないMJ字形。ツリーに出すと2万3千行かさばるだけなので、
       一覧側で灰色の1セクションとして眺められるようにする。
       （縮退先を持つJIS外のMJ字形はツリーのMJ列に出るので、ここには入らない） */
    function renderGaiji(container, targetChars, blk) {
      if (!mjmap) return 0;
      const items = [];
      mjmap.mj.forEach((m, i) => {
        if (!m[1]) return;
        // 縮退先が一覧に無い字（々〆〻 のような記号）しか無いMJは、どの群にも現れないので外字へ回す。
        // charLevel は第1〜4水準だけを持つ（外字は入れない）ので、この has() は水準字かどうかを見る
        const to = candByMj.get(i);
        if (to && to.some(([ji]) => charLevel.has(jisCh[ji]))) return;
        const ch = m[1];
        if (SYMBOL_CHARS.has(ch)) return; // 記号セクションに出しているので重ねない
        // 部首表もU+検索も基底字で持つので、IVS付きの札は基底でも当てる
        if (targetChars !== null && !targetChars.has(ch) && !targetChars.has(mjBase[i])) return;
        const code = ch.codePointAt(0);
        if (blk && cjkBlock(code) !== blk) return;
        items.push({ char: ch, mj: mjName(m[0]), code });
      });
      if (!items.length) return 0;
      items.sort((a, b) => a.code - b.code || a.mj.localeCompare(b.mj));

      // 外字は面区点を持たないので、水準側の「区」の札にあたるものがUnicodeブロックになる。
      // 区分を分けずに1本のグリッドのまま、ブロックが変わった最初のカードだけ札を出す。
      const base = listOrder.length;
      let prevBlock = null;
      items.forEach(it => {
        const blk2 = cjkBlock(it.code);
        listOrder.push({ char: it.char, level: 5, mj: it.mj, blk: blk2, tag: blk2 !== prevBlock ? blk2 : "" });
        prevBlock = blk2;
      });
      addSection(container, "lvl5", "MJ外字", items.length, base);
      return items.length;
    }

    /* ---- ツリーの行を組む ----
       行の並びは一覧のカード順。各カードの文字に関わる MJ をその下にぶら下げる。
       複数のJIS字に縮退するMJは、一覧で先に来るカードの群に1回だけ描く（下の shownPair）。

       同じカードの下は「縮退先の組み合わせ」＝枝でまとめ、組み合わせが小さい順に並べる。
       枝は自分を含む直近の枝を親にして、親から増えたぶんの字だけを描く。
       2字以上増える枝は枠で囲み、その中心から左へ出して └ で親に繋ぐ。
       横線はその枝の幹から右にしか伸びないので、交点に点を打たなくても読める。 */
    let treeDirty = false;
    function rebuildTree() {
      const pane = el("treePane");
      if (!mjmap) { pane.innerHTML = '<div class="tree-empty">縮退データ未読込</div>'; return; }
      // ツリーを閉じているあいだは組まない。5万4千行ぶんのレイアウト計算が一覧の描き直しに
      // 毎回乗ると、部首を解除しただけで1秒近く固まる。開いたときにまとめて組む。
      if (!document.body.classList.contains("tree-on")) { treeDirty = true; return; }
      treeDirty = false;

      treeRows = []; treeGroups = []; firstRowOf = [];
      let y = 0;
      const shownPair = new Set(); // 描いた (MJ index, 面区点の添字)
      drawnAt.clear();
      listOrder.forEach((it, i) => {
        firstRowOf[i] = treeRows.length;
        let mjs = (mjByChar.get(it.char) || []).slice();
        if (!mjs.length) return;
        // 縮退先として連れてきただけの字は、その字自身の例示字形と、フィルタに当たった字へ
        // 繋がるMJだけを出す。あめかんむりで引いたとき 覇 は 霸 の縮退先として出てくるが、
        // 雨と縁の無い異体字 覇󠄃(MJ024209) まで並べる筋合いは無い。
        // 直接当たった字（きへんの 松 など）は異体字ごと全部出す。
        if (shrinkPulled.has(it.char)) {
          mjs = mjs.filter(m => (repOf.has(m) && jisCh[repOf.get(m)] === it.char)
                             || (candByMj.get(m) || []).some(([ji]) => directHits.has(jisCh[ji])));
          if (!mjs.length) return;
        }
        /* この群で各MJに描く縮退先を決める。
           (1) 前の群で既に描いた (MJ, 縮退先) の組は二度描かない。
               惡(1-56-08) の群は 悪(1-16-13) の群と同じMJ・同じ縮退先を繰り返すだけなので、
               縮退が集まる側（一覧で先に来る方）に一本化する。
               邊󠄏(MJ026199) は 辺 の群に [辺 邊] で出ているので、邊 の群に重ねて出さない。
               群はそこに居るMJの縮退先を全部描くので、畳んでもその字の例示字形は先の群に出ている。
           (2) この群の字へのエッジより弱い根拠の縮退先は、この群では描かない。
               辺󠄂(MJ025759) は 辺 へ包摂（実線）、邊 へ親字（破線）で、[辺 邊] の枝に入れると
               邊 の下にぶら下がって「邊 を経て 辺 へ」と読めてしまう。辺 の群では 辺 ─ 辺󠄂 とだけ描き、
               邊 との関係は 邊 の群で 邊 - - 辺󠄂 として出す（(1) で 辺 は落ちる）。
           この群の字へのエッジが既に描かれているMJ、描く縮退先が無くなったMJは群から外す。 */
        const drawSet = new Map();
        mjs = mjs.filter(m => {
          const es = candByMj.get(m) || [];
          const own = es.find(([ji]) => jisCh[ji] === it.char);
          if (!own || shownPair.has(m + ":" + own[0])) return false;
          const keep = es.filter(([ji, ti]) => ti <= own[1] && !shownPair.has(m + ":" + ji));
          drawSet.set(m, keep);
          return true;
        });
        if (!mjs.length) return;
        mjs.forEach(m => drawSet.get(m).forEach(([ji]) => shownPair.add(m + ":" + ji)));

        // 字形が一致するMJ（自身の面区点がこの字）を先に見て、その字に0番を振る
        const isOwn = m => mjBase[m] === it.char;
        mjs.sort((a, b) => (isOwn(a) === isOwn(b) ? a - b : isOwn(a) ? -1 : 1));

        const byCh = new Map(), setOf = new Map(), tierOfRow = new Map(), tierOfEdge = new Map();
        const kjEdge = new Set(), repEdge = new Set();
        mjs.forEach(m => {
          let b = 0, worst = 0;
          drawSet.get(m).forEach(([ji, ti, kj, rep]) => {
            const ch = jisCh[ji];
            let t = byCh.get(ch);
            // 記号は1面1区・5区で第1〜4水準の外に居る。列が無いままだと 5列目＝MJ列へ
            // 落ちてMJの字形と重なるので、終着点側＝第1水準の列に寄せる。
            // 面区点は札に出るので 1-01-24 が第1水準でないことは読み取れる。
            if (!t) byCh.set(ch, t = { ch, jis: mjmap.jis[ji][0], idx: byCh.size,
                                       col: SYMBOL_CHARS.has(ch) ? 0 : (charLevel.get(ch) || 5) - 1 });
            b |= 1 << t.idx;
            if (ti > worst) worst = ti;          // 行の線はその行がぶら下がる一番弱い根拠に合わせる
            tierOfEdge.set(m + ":" + t.idx, ti);
            if (kj) kjEdge.add(m + ":" + t.idx);
            if (rep) repEdge.add(m + ":" + t.idx);
          });
          setOf.set(m, b);
          tierOfRow.set(m, worst);
        });
        const targets = [...byCh.values()];

        // 縮退先が少ない順。同数なら組み合わせ順 → 字形一致 → MJ番号。
        // 虼 のように「蝱 を経ずに直接 虻 へ行く」MJが上にまとまる。
        // 同じ組み合わせの中では、その組み合わせで増える字を自分の字形として持つMJを先頭に。
        // 惡 の枝の先頭が 䛩 になっていると、悪—惡 の線が 䛩 の行に出て読めない。
        // さらに、その面区点のJIS例示字形（X0213 包摂区分0）であるMJを優先する。
        // 悁 は MJ011568(IVS E0102) と MJ011569(IVS E0101) が同じ組み合わせを持つが、
        // 1-55-90 に割り当てられているのは 69 の方なので、そちらが先頭に来る。
        const pop = b => (b >>> 0).toString(2).replace(/0/g, "").length;
        const hasTarget = (m, ch) => { const t = byCh.get(ch); return t && (setOf.get(m) & (1 << t.idx)) ? 0 : 1; };
        const repRank = m => { const j = repOf.get(m); return j == null ? 1 : hasTarget(m, jisCh[j]); };
        const selfTarget = m => hasTarget(m, mjBase[m]);
        mjs.sort((a, b) => pop(setOf.get(a)) - pop(setOf.get(b)) || setOf.get(a) - setOf.get(b)
          || repRank(a) - repRank(b)
          || selfTarget(a) - selfTarget(b)
          || (isOwn(a) === isOwn(b) ? a - b : isOwn(a) ? -1 : 1));

        // 同じ組み合わせの連なりを1つの枝にする
        const branches = [];
        mjs.forEach((m, k) => {
          const last = branches[branches.length - 1];
          if (last && last.bits === setOf.get(m)) { last.last = k; return; }
          branches.push({ bits: setOf.get(m), first: k, last: k });
        });

        // 親は自分を含む直近の枝。縮退先の少ない順に並べてあるので親は必ず自分より前に居る。
        // 包含関係が無い枝も、群の字だけは枝0が描いているので親を0に寄せる。
        const parentOf = branches.map((br, bi) => {
          for (let j = bi - 1; j >= 0; j--) {
            if ((branches[j].bits & br.bits) === branches[j].bits) return j;
          }
          return bi > 0 ? 0 : -1;
        });

        /* 枝を「親のすぐ後ろに子」の順へ並べ替える。
           縮退先の数の順に並べただけだと親と子のあいだに無関係な枝が挟まり、
           増える字の無い枝が1つ上の枝にぶら下がっているように見える。
           国の群なら 囶(MJ008844) と 圀(MJ008853) のあいだに MJ008843 が落ちて、
           MJ008843 が 1-51-91 へ縮退しているかのように読めていた。 */
        const kids = branches.map(() => []);
        const order = [];
        parentOf.forEach((pi, bi) => { if (pi >= 0) kids[pi].push(bi); else order.push(bi); });
        for (let n = 0; n < order.length; n++) order.splice(n + 1, 0, ...kids[order[n]]);
        const at = new Map(order.map((bi, i) => [bi, i]));
        const reordered = order.map(bi => {
          const br = branches[bi];
          const first = mjs.length;                       // 並べ替えたMJは末尾へ積んでいく
          for (let k = br.first; k <= br.last; k++) mjs.push(mjs[k]);
          return { bits: br.bits, first, last: mjs.length - 1, parent: at.has(parentOf[bi]) ? at.get(parentOf[bi]) : -1 };
        });
        const cut = reordered[0].first;                   // 元の並びを捨てて添字を詰め直す
        mjs.splice(0, cut);
        reordered.forEach(br => { br.first -= cut; br.last -= cut; });
        branches.length = 0;
        branches.push(...reordered);

        const drawn = new Set();
        branches.forEach((br, bi) => {
          // 親から増えたぶん。ただし既に他の枝が描いた字は二度描かない
          // （包含関係が無い枝どうしだと、親を枝0に寄せた結果ぶつかることがある）
          const base = bi === 0 ? 0 : branches[br.parent].bits;
          br.delta = targets.filter(t => (br.bits & (1 << t.idx)) && !(base & (1 << t.idx)) && !drawn.has(t.idx));
          br.delta.forEach(t => drawn.add(t.idx));
          // 幹の線種は行ごとに rowHtml で決める（自分の行へはその行の根拠、子の枝へはその枝が親へ上がる根拠）
          // 親へ上がる線は、親側の縮退先に対する根拠で描く。新旧字体かどうかは枝の性質として持つ
          const up = targets.filter(t => (base & (1 << t.idx)));
          br.upTier = Math.max(0, ...up.map(t => tierOfEdge.get(mjs[br.first] + ":" + t.idx) || 0));
          br.kj = false; br.rep = false;
          for (let k = br.first; k <= br.last && !(br.kj && br.rep); k++) {
            br.kj = br.kj || up.some(t => kjEdge.has(mjs[k] + ":" + t.idx));
            br.rep = br.rep || up.some(t => repEdge.has(mjs[k] + ":" + t.idx));
          }

          // 増えたぶんの字を列ごとに縦へ積み、枠の中心を幹の位置にする
          const slot = {};
          br.delta.forEach(t => { t.slot = slot[t.col] || 0; slot[t.col] = t.slot + 1; });
          br.lines = Math.max(1, ...br.delta.map(t => slot[t.col]));
          const xs = br.delta.map(t => t.col * COL_W + COL_W / 2);
          br.delta.forEach((t, k) => { t.x = xs[k]; });
          if (!xs.length) {
            // 増える字が無い枝（既に描かれている字だけで出来ている）は親の幹にそのまま下げる
            br.loX = br.spineX = br.parent >= 0 ? branches[br.parent].spineX : COL_W / 2;
          } else {
            br.loX = Math.min(...xs);
            br.spineX = (br.loX + Math.max(...xs)) / 2;
          }
        });
        branches.forEach(br => {
          // 幹は自分の行と、自分にぶら下がる枝の先頭行まで通す
          br.to = br.last;
          branches.forEach(c => { if (c.parent === branches.indexOf(br) && c.first > br.to) br.to = c.first; });
        });

        branches.forEach((br, bi) => br.delta.forEach(t => {
          t.branch = bi;
          // その字が実際に描かれている行。群を畳んだ字へ飛ぶときの行き先になる
          if (!drawnAt.has(t.ch)) drawnAt.set(t.ch, treeRows.length + br.first);
        }));
        const gi = treeGroups.length;
        treeGroups.push({ branches, targets, row0: treeRows.length });
        const brOf = [];
        branches.forEach((br, bi) => { for (let k = br.first; k <= br.last; k++) brOf[k] = bi; });
        mjs.forEach((m, k) => {
          const bi = brOf[k], br = branches[bi];
          const ex = (k === br.first ? br.lines : 1) - 1;
          treeRows.push({ g: gi, mj: m, k, b: bi, anchor: i, y, h: ROW_H + ex * SUB_H, ex, top: k === 0,
                          tier: tierOfRow.get(m) || 0 });
          y += ROW_H + ex * SUB_H;
        });
      });

      let head = '<div class="tree-head" style="width:' + COL_W * 5 + 'px">';
      for (let c = 0; c < 5; c++) head += `<div id="colh${c}" style="width:${COL_W}px">${COL_LABEL[c]}</div>`;
      head += '<div id="treeNote" class="tree-note" hidden></div>';
      pane.innerHTML = head + '</div><div id="treeBody" style="width:' + COL_W * 5 + 'px;height:' + y + 'px"></div>';
      focusCol = -1;
      renderTreeWindow();
      syncTree();
    }

    function nodeHtml(x, top, color, ch, meta, on, tint, copy) {
      return `<div class="tree-node${on ? " hit" : ""}" style="left:${x}px;top:${top}px">`
        + `<span class="g" style="color:${color}${on ? ";background:" + tint + "40" : ""}" data-c="${ch}" data-k="${ch}">${ch}</span>`
        + `<span class="m"${copy ? ` data-copy="${copy}" title="クリックでコピー"` : ""}>${meta}</span></div>`;
    }

    // その行からその縮退先へのエッジの根拠の段と、新旧字体か・JIS例示字形か
    function rowEdge(mi, t) {
      for (const [ji, ti, kj, rep, why] of candByMj.get(mi) || []) if (jisCh[ji] === t.ch) return { tier: ti, kj, rep, why };
      return { tier: 0, kj: false, rep: false, why: "" };
    }
    // 線の tooltip。「字形 → 縮退先(面区点): 根拠」を縮退先ごとに1行
    const esc = str => String(str).replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;");
    const edgeTitle = (mi, ts) => esc(ts.map(t => `${mjmap.mj[mi][1]} → ${t.ch}(${t.jis}): ${rowEdge(mi, t).why || "?"}`).join("\n"));
    const lineCls = (tier, kj, rep) => `t${tier}${kj ? " kj" : ""}${rep ? " rep" : ""}`;

    function rowHtml(r, hit, tint) {
      const g = treeGroups[r.g];
      const br = g.branches[r.b];
      const parent = br.parent >= 0 ? g.branches[br.parent] : null;
      const m = mjmap.mj[r.mj];
      const base = mjBase[r.mj];
      const glyph = m[1]; // IVS付きなら基底＋選択子でIPAmj明朝が字形を選ぶ
      const mjX = 4 * COL_W + COL_W / 2;
      // 枠を作る枝の先頭行だけは、横線を枠の中心に通して「枠の中心から左へ出す」形にする
      const boxed = r.k === br.first && br.delta.length > 1;
      const lineY = boxed ? br.lines * SUB_H / 2 - 3 : r.ex * SUB_H + 16;
      const mjTop = lineY - 17;

      const on = base === hit || (r.k === br.first && br.delta.some(t => t.ch === hit));

      let h = `<div class="tree-row${r.top ? " grp" : ""}" style="top:${r.y}px;height:${r.h}px`
        + (on ? `;background:${tint}1a` : "") + '">';

      // 横線。親の縮退先への繋がりは枝の入れ子（縦の幹）で表しているので、
      // 親まで戻る線分を引くのは枝の先頭行だけ。2行目以降で引くと、上に幹が無い位置から
      // 線が生えて「その行が直接そこへ縮退している」ように見えてしまう。
      // 秌(MJ019007) なら MJ〜秌 は包摂なので実線、秌〜秋 は戸籍法通達なので破線になる。
      // 線はその行がぶら下がる一番弱い根拠で描く。その根拠が新旧字体なら橙の実線にする。
      // ここで .kj を付けないと、曾→曽 のような新旧字体が灰の破線（＝その他の法令）に見えてしまう
      const ownEdges = br.delta.map(t => rowEdge(r.mj, t));
      const own = Math.max(0, ...ownEdges.map(e => e.tier));
      const ownKj = ownEdges.some(e => e.tier === own && e.kj);
      const ownRep = ownEdges.some(e => e.rep);
      // 親へ戻る線と、親の幹のうちこの枝へ降りてくる区間は、この枝のMJから親側の縮退先への根拠で描く
      const upTargets = parent ? g.targets.filter(t => parent.bits & (1 << t.idx)) : [];
      if (r.k === br.first && parent && parent.spineX < br.loX) {
        h += `<div class="tree-line ${lineCls(br.upTier, br.kj, br.rep)}" title="${edgeTitle(r.mj, upTargets)}" style="left:${parent.spineX}px;top:${lineY}px;width:${br.loX - parent.spineX}px"></div>`;
      }
      const from = r.k === br.first ? br.loX : br.spineX;
      h += `<div class="tree-line ${lineCls(own, ownKj, ownRep)}" title="${edgeTitle(r.mj, br.delta)}" style="left:${from}px;top:${lineY}px;width:${mjX - from}px"></div>`;

      /* 幹（縦線）。自分の枝と、この行を通過する先祖の枝の両方を描く。
         幹の区間は「どの行へ降りていくか」で根拠が変わる。枝自身の行どうしを繋ぐ区間は枝の根拠、
         枝の最後の行から下の、子の枝へ降りていく区間は、その子の枝が親へ上がる根拠で描く。
         1行の中でも横線の上と下で行き先が違う（上は自分へ、下は次の行へ）ので、2本に分けて描く。 */
      g.branches.forEach((b2, bi) => {
        if (r.k < b2.first || r.k > b2.to) return;
        const rowMj = k => treeRows[g.row0 + k].mj;
        const styleTo = k => {
          if (k <= b2.last) {
            // 枝自身の行へ降りる区間は、その行のMJから枝の縮退先への根拠。横線と同じ線種になる
            const es = b2.delta.map(t => rowEdge(rowMj(k), t));
            const tier = Math.max(0, ...es.map(e => e.tier));
            return { cls: lineCls(tier, es.some(e => e.tier === tier && e.kj), es.some(e => e.rep)), title: "" };
          }
          const c = g.branches.filter(c => c.parent === bi && c.first >= k).sort((a, b) => a.first - b.first)[0];
          const up = g.targets.filter(t => b2.bits & (1 << t.idx));
          return { cls: lineCls(c.upTier, c.kj, c.rep), title: edgeTitle(rowMj(c.first), up) };
        };
        const top = r.k === b2.first ? r.ex * SUB_H + 28 : 0;
        const bus = (y0, y1, st) => y1 > y0 ? `<div class="tree-bus ${st.cls}"${st.title ? ` title="${st.title}"` : ""} style="left:${b2.spineX}px;top:${y0}px;height:${y1 - y0}px"></div>` : "";
        h += bus(top, Math.min(lineY, r.h), styleTo(r.k));                    // この行の横線まで
        if (r.k < b2.to) h += bus(Math.max(top, lineY), r.h, styleTo(r.k + 1)); // 次の行へ
      });

      if (r.k === br.first) {
        // 2字以上まとめて増える枝は枠で囲み、この枠がひとかたまりであることを示す
        if (br.delta.length > 1) {
          const l = Math.min(...br.delta.map(t => t.x)) - 30, w = Math.max(...br.delta.map(t => t.x)) + 30 - l;
          h += `<div class="tree-box" style="left:${l}px;top:-1px;width:${w}px;height:${br.lines * SUB_H + 2}px"></div>`;
        }
        br.delta.forEach(t => {
          h += nodeHtml(t.x, (r.ex - t.slot) * SUB_H - 1, LEVEL_COLOR[t.col + 1], t.ch, t.jis, t.ch === hit, tint, t.jis);
        });
      }
      return h + nodeHtml(mjX, mjTop, LEVEL_COLOR[5], glyph, mjName(m[0]), base === hit, tint, mjName(m[0])) + "</div>";
    }

    // 見えている行だけDOMにする（全行は10万近くになるので実体化しない）
    function renderTreeWindow() {
      const pane = el("treePane"), body = el("treeBody");
      if (!body || !treeRows.length) return;
      const top = pane.scrollTop, h = pane.clientHeight;
      let a = lowerBound(top - ROW_H * 4), b = a;
      while (b < treeRows.length && treeRows[b].y < top + h + ROW_H * 4) b++;
      if (b === a && a < treeRows.length) b = a + 1;
      const tint = LEVEL_COLOR[charLevel.get(hoverChar)] || LEVEL_COLOR[5];
      let out = "";
      for (let i = a; i < b; i++) out += rowHtml(treeRows[i], hoverChar, tint);
      body.innerHTML = out;
    }

    function lowerBound(y) {
      let lo = 0, hi = treeRows.length - 1, r = 0;
      while (lo <= hi) { const m = (lo + hi) >> 1; if (treeRows[m].y >= y) { r = m; hi = m - 1; } else lo = m + 1; }
      return r;
    }

    /* ---- スクロール同期 ----
       駆動側は「最後に触ったペイン」に固定する。両方のonscrollが互いを動かすと往復ループになるため。
       水平方向のフォーカス移動はscrollLeftしか変えないので、scrollTopが変わった時だけ同期を走らせる。 */
    let driver = null, guard = false, curAnchor = 0, focusCol = -1, hoverChar = null;
    let lastListTop = -1, lastTreeTop = -1;

    function paneTop(node, pane) {
      return node.getBoundingClientRect().top - pane.getBoundingClientRect().top + pane.scrollTop;
    }

    /* ---- 一覧の仮想スクロール ----
       カードは5万枚を超える。全部DOMに置くと20万ノードになり、絞り込みのたびに700msかかる。
       ツリーのペインと同じで、位置は測らずに計算し、見えている行だけ実体化する。
       測るのは「カード1行の送り」と「各グリッドの容器内での位置」だけで、あとは算術で出す。
       カードの left/top/width はこちらが書き込むので、ブラウザの実際の配置とずれようがない。 */
    const GAP = 10, MIN_W = 80;   // .grid が持っていた gap:10px と minmax(80px,1fr) の写し
    const OVER = 4;               // 窓の上下に余分に組む行数。窓がこの帯から出るまでは組み直さない

    // そのセクションの j 枚目のカードの位置。幅は % なので、列数が変わらない伸縮は
    // ブラウザが追随する（auto-fill の 1fr が持っていた性質をそのまま残す）
    const cardPos = j => `left:calc((100% + ${GAP}px)*${j % cols}/${cols});`
      + `top:${Math.floor(j / cols) * pitch}px;width:calc((100% + ${GAP}px)/${cols} - ${GAP}px)`;

    // listOrder の添字 -> そのカードが属するセクション。記号は listOrder に積まないので base<0 を飛ばす
    function secOf(i) {
      let s = null;
      for (const x of sections) if (x.base >= 0 && x.base <= i) s = x;
      return s;
    }
    // listOrder の添字 -> カードの上端（容器内座標）。paneTop と同じ基準
    function cardY(i) {
      const s = secOf(i);
      return s ? s.top + Math.floor((i - s.base) / cols) * pitch : 0;
    }
    // その高さに掛かっている行の最後のカード。カードのDOMを二分探索していた頃と同じ答えになる
    // （同じ行のカードは上端が等しいので、あの二分探索は必ず行末を返していた）
    function cardIndexAt(y) {
      if (!pitch) return 0;   // まだ測れていない（幅0で畳まれている）
      let s = null;
      for (const x of sections) if (x.base >= 0 && x.top <= y) s = x;
      if (!s) return 0;
      const row = Math.min(s.rows - 1, Math.max(0, Math.floor((y - s.top) / pitch)));
      return Math.min(s.base + row * cols + cols - 1, s.base + s.n - 1);
    }

    /* 一覧の見えている範囲を容器内の座標で返す。一覧が独自のスクロール容器になるのは
       広い画面でツリーONのときだけで（CSS: body.tree-on #kanjiContainer{overflow-y:auto}）、
       それ以外はページごと動く。paneTop と同じ基準なので cardY とそのまま比べられる。
       狭い画面ではツリーは下からのシートなので、一覧はページのまま流す。一覧を容器にすると、
       全幅の一覧がスワイプを全部受けてしまい、一覧を先頭まで戻さないと上の枠や設定へ戻れない */
    const treeOn = () => document.body.classList.contains("tree-on");
    const narrow = matchMedia('(max-width: 640px)');
    const listScrolls = () => treeOn() && !(narrow.matches && showsList());
    // シートが一覧の下半分を覆っている高さ（CSS の 50vh + 閉じる帯 40px）
    const sheetH = () => narrow.matches && treeOn() && document.body.classList.contains("tree-sheet") ? innerHeight / 2 + 40 : 0;
    function listView() {
      const pane = el("kanjiContainer");
      return listScrolls() ? { pane, top: pane.scrollTop, h: pane.clientHeight }
                           : { pane, top: -pane.getBoundingClientRect().top, h: innerHeight };
    }
    function listScrollTo(y) {
      const v = listView();
      if (listScrolls()) { v.pane.scrollTop = y; lastListTop = v.pane.scrollTop; }
      else window.scrollTo(0, window.scrollY + y - v.top - navH()); // 上端に貼り付いた帯の下に出す
    }

    // 見出しとグリッドを1組作って控える。カードの中身は窓に入ったときに make(j) で組む
    function addSection(container, cls, label, n, base, make) {
      const sep = document.createElement("div");
      sep.className = "level-separator " + cls;
      sep.innerHTML = `<span>${label}</span>`;
      const grid = document.createElement("div");
      grid.className = "grid";
      container.append(sep, grid);
      sections.push({ sep, grid, label, lv: +(cls.match(/lvl(\d)/) || [])[1] || 5, n, base,
                      make: make || (j => listCardHtml(base + j, j)), top: 0, rows: 0, a: -1, b: -1 });
    }

    /* 列数もカードの高さもCSSから決まる値で、宣言としては読めない。プローブを1枚だけ挿して
       測り、あとは全部計算で出す。グリッドには行数ぶんの高さを入れておくので、見出しのsticky
       もページ全体のスクロール量も、カードを全部置いていた頃と1pxも変わらない。 */
    function relayout() {
      if (!sections.length) return;
      const pane = el("kanjiContainer"), g0 = sections[0].grid, w = g0.clientWidth;
      if (!w) return;   // 変体仮名タブに居るあいだ／一覧OFF。表に戻ったときに測り直す
      cols = Math.max(1, Math.floor((w + GAP) / (MIN_W + GAP)));  // auto-fill の列数と同じ式
      g0.innerHTML = sections[0].make(0);
      pitch = g0.firstElementChild.getBoundingClientRect().height + GAP;
      console.assert(pitch > GAP, "カードの高さが測れていません");
      sections.forEach(s => {
        s.rows = Math.ceil(s.n / cols);
        s.grid.style.height = (s.rows * pitch - GAP) + "px";  // 最終行の後ろにgapは付かない
        s.a = s.b = -1;                                       // 窓を捨てて次の描画で組み直させる
      });
      sections.forEach(s => s.top = paneTop(s.grid, pane));   // 高さを入れ終えてから測る
      renderCardWindow();
    }

    // 見えている行だけ実体化する。帯を少し広めに組み、窓が帯から出たときだけ組み直す
    // （スクロールのたびに innerHTML を捨てると :hover が落ちてカードがちらつく）
    function renderCardWindow() {
      if (!pitch || !sections.length) return;
      const v = listView();
      // 畳まれている最中は窓の高さが0になる。ここで全セクションを空にすると、
      // 高さが戻っても引き直す機会が無いまま真っ白になるので、触らずに帰る
      if (v.h <= 0) return;
      for (const s of sections) {
        const a0 = Math.max(0, Math.min(s.rows, Math.floor((v.top - s.top) / pitch)));
        const b0 = Math.max(0, Math.min(s.rows, Math.ceil((v.top + v.h - s.top) / pitch)));
        // 窓から外れたセクションは空にする。残しておくと、光らせた1枚のように
        // もう古くなった中身がそのまま居座る（0,0 は空の印で、二度目は素通りする）
        if (b0 <= a0) { if (s.a !== 0 || s.b !== 0) { s.grid.innerHTML = ""; s.a = s.b = 0; } continue; }
        if (a0 >= s.a && b0 <= s.b) continue;   // まだ帯の中
        const a = Math.max(0, a0 - OVER), b = Math.min(s.rows, b0 + OVER);
        let out = "";
        for (let j = a * cols, e = Math.min(b * cols, s.n); j < e; j++) out += s.make(j);
        s.grid.innerHTML = out; s.a = a; s.b = b;
      }
    }
    // 光らせる1枚が変わったときなど、帯が動いていなくても組み直させる
    function redrawCards() {
      sections.forEach(s => { s.a = s.b = -1; });
      renderCardWindow();
    }

    function setAnchor(i) {
      if (i === curAnchor) return false;
      curAnchor = i;
      const lv = listOrder[i] ? (charLevel.get(listOrder[i].char) || 5) : 5;
      const c = lv === 5 ? 4 : lv - 1;
      if (c !== focusCol) {
        focusCol = c;
        for (let k = 0; k < 5; k++) { const e = el("colh" + k); if (e) e.classList.toggle("foc", k === c); }
        // MJ列は常に右端に居るので、横に逃がすと肝心の行末が隠れる。
        // 5列とも窓に収まる幅にして、フォーカスは見出しの強調だけで示す。
        const tp = el("treePane");
        if (COL_W * 5 > tp.clientWidth) tp.scrollLeft = Math.max(0, Math.min(COL_W * 5 - tp.clientWidth, c * COL_W + COL_W / 2 - tp.clientWidth / 2));
      }
      return true;
    }

    // 一覧 → ツリー
    // 一覧の i 番目のカードに合わせてツリーを送る
    function alignTree(i) {
      setAnchor(i);
      const tp = el("treePane");
      const want = treeRows[firstRowOf[i]] ? treeRows[firstRowOf[i]].y : 0;
      if (Math.abs(tp.scrollTop - want) > 1) { tp.scrollTop = want; lastTreeTop = tp.scrollTop; }
      renderTreeWindow();
    }

    function syncTree() {
      if (!mjmap || !treeRows.length || !sections.length || !showsList()) return;
      alignTree(cardIndexAt(listView().top + 8));
    }

    // ツリー → 一覧
    function syncList() {
      if (!mjmap || !treeRows.length) return;
      const tp = el("treePane");
      const r = treeRows[lowerBound(tp.scrollTop)];
      if (!r) return;
      setAnchor(r.anchor);
      // カードは実体化していなくても位置は計算で出るので、画面の外の字にも効く
      if (showsList() && sections.length) {
        const want = cardY(r.anchor) - 8, v = listView();
        if (Math.abs(v.top - want) > 1) listScrollTo(want);
      }
      renderTreeWindow();
    }

    function wireSync() {
      const list = el("kanjiContainer"), tree = el("treePane");
      [[list, "list"], [tree, "tree"]].forEach(([p, name]) => {
        p.addEventListener("wheel", () => driver = name, { passive: true });
        p.addEventListener("pointerdown", () => driver = name);
      });
      list.addEventListener("scroll", () => {
        renderCardWindow();   // 窓の描き直しはどちらが駆動していても要る（自分で動かした時も含む）
        if (list.scrollTop === lastListTop) return;
        lastListTop = list.scrollTop;
        if (guard || driver === "tree") return;
        guard = true; syncTree(); requestAnimationFrame(() => guard = false);
      }, { passive: true });
      tree.addEventListener("scroll", () => {
        if (tree.scrollTop === lastTreeTop) return; // 水平フォーカス移動では発火させない
        lastTreeTop = tree.scrollTop;
        if (guard || driver === "list") { renderTreeWindow(); return; }
        guard = true; syncList(); requestAnimationFrame(() => guard = false);
      }, { passive: true });
      // 一覧が容器でないときはページが動くので、窓はこちらで引き直す。狭い画面のシートのツリーも
      // ここから合わせる。ツリーを触っているあいだ（driver が tree）は、ツリーが一覧を動かしている側なので返さない
      window.addEventListener("scroll", () => {
        if (listScrolls()) return;
        renderCardWindow();
        if (!treeOn() || guard || driver === "tree") return;
        guard = true; syncTree(); requestAnimationFrame(() => guard = false);
      }, { passive: true });
      // ツリーの外を触ったら一覧（ページ）の側が駆動する。ページのスクロールは一覧の外からも始まる
      ["pointerdown", "wheel"].forEach(n => window.addEventListener(n, e => {
        if (!e.target.closest || !e.target.closest("#treePane")) driver = "list";
        showTreeNote("");
      }, { capture: true, passive: true }));
      // 幅が変われば列数が変わる。窓の伸縮のほか、ツリーの出入りやタブの切り替えでも
      // 一覧の幅は変わり、隠れているあいだは0で測れない。窓と容器の両方を見張る
      // （容器だけだと窓の伸縮を取りこぼす環境があり、窓だけだとペインの出入りを拾えない）。
      window.addEventListener("resize", relayout);
      if (window.ResizeObserver) new ResizeObserver(() => relayout()).observe(el("kanjiContainer"));
      // 見出しの高さはグリフ依存なので、フォントが遅れて来たら位置を測り直す
      if (document.fonts) document.fonts.ready.then(relayout);
    }

    // ホバーは強調するだけ。マウスを乗せただけで表示が動くと落ち着いて読めないので、
    // 実際にスクロールさせるのは右クリック（jumpToChar）に限る。
    function setHover(ch) {
      if (ch === hoverChar) return;
      hoverChar = ch;
      if (mjmap && document.body.classList.contains("tree-on")) renderTreeWindow();
    }
    // 字の上に来た時だけ更新する。隙間を通っただけで消えると、
    // 再描画でカーソル下の要素が入れ替わるたびにハイライトが点滅してしまう。
    // カードのクリックは委譲で受ける（5万枚ぶんのハンドラを張らないため）
    el("kanjiContainer").addEventListener("click", e => {
      const c = e.target.closest(".card");
      if (!c) return;
      copyText(c.dataset.char, `「${c.dataset.char}」`);
      showCharParts(c.dataset.char);
      // 狭い画面ではツリーが横に無いので、タップした字の行へ送ってシートを開く
      if (treeOn() && narrow.matches) jumpToChar(c.dataset.char);
    });
    el("treeClose").addEventListener("click", () => document.body.classList.remove("tree-sheet"));

    /* スマホには右クリックが無いので、長押しを右クリックとして扱う。Android は長押しで contextmenu を
       出すが iOS は出さないので、自分で数えて同じイベントを送る。指が動けばスクロールとみなしてやめる。
       送り先は押した要素ではなくその位置の要素にする。押しているあいだに窓が組み直されて外れることがある */
    function longPressAsContext(root) {
      let timer = 0, x = 0, y = 0, touch = false, fired = false;
      const stop = () => clearTimeout(timer);
      root.addEventListener("pointerdown", e => {
        touch = e.pointerType !== "mouse"; fired = false;
        if (!touch) return;
        x = e.clientX; y = e.clientY;
        stop();
        timer = setTimeout(() => {
          fired = true;
          const t = document.elementFromPoint(x, y);
          if (t && root.contains(t)) t.dispatchEvent(new MouseEvent("contextmenu", { bubbles: true, cancelable: true, clientX: x, clientY: y }));
        }, 500);
      });
      root.addEventListener("pointermove", e => { if (Math.hypot(e.clientX - x, e.clientY - y) > 8) stop(); });
      ["pointerup", "pointercancel"].forEach(n => root.addEventListener(n, stop));
      root.addEventListener("contextmenu", e => { if (e.isTrusted && touch) { stop(); fired = true; } });
      // 長押しを離したときのタップでコピーまで走らせない
      root.addEventListener("click", e => { if (fired) { fired = false; e.stopPropagation(); e.preventDefault(); } }, true);
    }
    longPressAsContext(el("kanjiContainer"));
    longPressAsContext(el("treePane"));
    el("kanjiContainer").addEventListener("mouseover", e => {
      const c = e.target.closest(".card");
      if (c) setHover(c.dataset.char);
    });
    el("kanjiContainer").addEventListener("mouseleave", () => setHover(null));
    el("treePane").addEventListener("mouseover", e => {
      const n = e.target.closest(".tree-node");
      if (n) setHover(n.querySelector(".g").dataset.k);
    });
    el("treePane").addEventListener("mouseleave", () => setHover(null));

    // 右クリックでメニューを出す（両ペインとも）
    /* 右クリックのメニュー。この字へ移動するか、この字を組み立てている部品・辞書の部首・IDS をコピーする。
       部品は枠に入れるときと同じ「位置 部品」で並べ、コピーするのは部品の字だけ */
    function onContext(e, ch) {
      if (!ch) return;
      e.preventDefault();
      const base = Array.from(ch)[0];
      const items = [{ label: treeOn() ? 'この字へ移動（一覧と縮退ツリー）' : 'この字へ移動', run: () => {
        if (!jumpToChar(ch)) el("mjmapStatus").textContent = `「${ch}」は一覧にありません`;
      } }, null];
      // 字そのもの（外字は IVS ごと）、符号位置、MJ 番号
      const ucs = Array.from(ch).map(c => 'U+' + c.codePointAt(0).toString(16).toUpperCase().padStart(4, '0')).join(' ');
      items.push({ label: `<b>${ch}</b> をコピー`, run: () => copyText(ch, `「${ch}」`) });
      items.push({ label: `${ucs} をコピー`, run: () => copyText(ucs, ucs) });
      const mj = mjNameOf(ch);
      if (mj) items.push({ label: `${mj} をコピー`, run: () => copyText(mj, mj) });
      const parts = topParts(base, lookupIds);
      const rad = dictRadicalOf(base);
      const same = sameShapeSteps(base);
      if (parts.length || rad || same) items.push(null);
      if (same) items.push({ label: 'この字と同じ組み立てで探す', run: () => {
        nestMode = true;
        syncMode();
        setNestSteps(same);
      } });
      // 部品ごとに 1 行。コピーと条件に入れるを同じ行に並べる（別の行にすると部品の数の倍の行になってかさばる）
      const row = (label, copy, pos, part) => {
        const add = partAction(pos, part);
        return { label, actions: [{ text: 'コピー', run: () => copyText(copy, `「${copy}」`) }, ...(add ? [{ text: '条件に入れる', run: add }] : [])] };
      };
      const seen = new Set();
      parts.forEach(([pos, part]) => {
        if (seen.has(pos + part)) return;
        seen.add(pos + part);
        items.push(row(`${SLOT_LABEL[pos]} <b>${part}</b>`, part, pos, part));
      });
      if (rad) {
        const g = slotGlyph('ぶしゅ', rad);
        items.push(row(radicalLabel(base, rad).replace(g + '部', `<b>${g}</b>部`), g, 'ぶしゅ', rad));
      }
      openCtxMenu(e.clientX, e.clientY, `「${base}」`, items);
    }
    /* 字の一番外の組み立てを、組立検索の段にする（椅 ⿰木奇 -> 偏 木、空いた所 奇）。
       引数が部品 1 字でなく形のときは、その側は穴のままにする。位置に言えない字（⿻・⿲⿳）は null */
    function sameShapeSteps(ch) {
      const r = idsArgs(lookupIds(ch));
      if (!r) return null;
      const [op, args] = r;
      const pos = { '⿰': ['へん', 'つくり'], '⿱': ['かんむり', 'あし'], '⿸': ['たれ'], '⿺': ['にょう'] }[op]
        || ('⿴⿵⿶⿷⿹'.includes(op) || (op === '⿻' && args[0] === '冂') ? ['かまえ'] : null);
      if (!pos) return null;
      const one = a => Array.from(a).length === 1 && !isPlaceholder(a) ? a : null;
      const [a0, a1] = args.map(one);
      // 1 段目は外側（囲い）か左・上の部品。それが形なら、右・下の部品から始めて反対側を穴にする
      if (a0) return [[pos[0], a0], ...(a1 ? [['あな', a1, [1]]] : [])];
      return a1 && pos[1] ? [[pos[1], a1]] : null;
    }
    /* 字の MJ 番号。外字の札（IVS 付き）はその字形の MJ、水準字はその面区点の例示字形（代表）の MJ。
       mjmap を読んでいないときは出さない */
    let mjOfGlyph = null, mjOfGlyphFor = null;   // 字形（IVS 込み）-> MJ index。mjmap を読み直したら組み直す
    function mjNameOf(ch) {
      if (!mjmap) return null;
      if (mjOfGlyphFor !== mjmap) {
        mjOfGlyph = new Map();
        mjmap.mj.forEach((m, i) => { if (m[1] && !mjOfGlyph.has(m[1])) mjOfGlyph.set(m[1], i); });
        mjOfGlyphFor = mjmap;
      }
      const base = Array.from(ch)[0];
      const i = Array.from(ch).length > 1 ? mjOfGlyph.get(ch)
        : (mjByChar.get(base) || []).find(i => mjBase[i] === base && repOf.has(i)) ?? mjOfGlyph.get(ch);
      return i == null ? null : mjName(mjmap.mj[i][0]);
    }
    const dictRadicalOf = base => Object.keys(DICT_RADICALS).find(r => DICT_RADICALS[r].includes(base))
      || (mjmap && mjmap.dictRadicals ? Object.keys(mjmap.dictRadicals).find(r => mjmap.dictRadicals[r].includes(base)) : null);

    // メニューはカーソルの位置に出し、画面からはみ出すなら内側へ寄せる。Esc・外側のクリック・スクロールで閉じる
    function openCtxMenu(x, y, title, items) {
      closeCtxMenu();
      const m = document.createElement('div');
      m.className = 'ctx-menu';
      m.id = 'ctxMenu';
      m.setAttribute('role', 'menu');
      m.innerHTML = `<div class="ctx-title">${title}</div>`;
      items.forEach(it => {
        if (!it) { m.appendChild(Object.assign(document.createElement('div'), { className: 'ctx-sep' })); return; }
        if (it.actions) {
          // 1 つのものに操作が複数あるときは、名前の横に操作のボタンを並べる
          const r = Object.assign(document.createElement('div'), { className: 'ctx-row' });
          r.appendChild(Object.assign(document.createElement('span'), { innerHTML: it.label }));
          it.actions.forEach(x => {
            const b = Object.assign(document.createElement('button'), { type: 'button', textContent: x.text });
            b.setAttribute('role', 'menuitem');
            b.setAttribute('aria-label', `${r.textContent} ${x.text}`);
            b.onclick = () => { closeCtxMenu(); x.run(); };
            r.appendChild(b);
          });
          m.appendChild(r);
          return;
        }
        const b = document.createElement('button');
        b.type = 'button';
        b.setAttribute('role', 'menuitem');
        b.innerHTML = it.label;
        b.onclick = () => { closeCtxMenu(); it.run(); };
        m.appendChild(b);
      });
      document.body.appendChild(m);
      const r = m.getBoundingClientRect(), W = document.documentElement.clientWidth, H = innerHeight;
      m.style.left = `${Math.max(8, Math.min(x, W - r.width - 8))}px`;
      m.style.top = `${Math.max(8, Math.min(y, H - r.height - 8))}px`;
      m.querySelector('button').focus({ preventScroll: true });
    }
    function closeCtxMenu() { const m = el('ctxMenu'); if (m) m.remove(); }
    document.addEventListener('pointerdown', e => { if (!e.target.closest('#ctxMenu')) closeCtxMenu(); });
    window.addEventListener('scroll', closeCtxMenu, true);
    document.addEventListener('keydown', e => {
      const m = el('ctxMenu');
      if (!m) return;
      if (e.key === 'Escape') { closeCtxMenu(); return; }
      if (e.key !== 'ArrowDown' && e.key !== 'ArrowUp') return;
      e.preventDefault();
      const bs = [...m.querySelectorAll('button')], i = bs.indexOf(document.activeElement);
      bs[(i + (e.key === 'ArrowDown' ? 1 : -1) + bs.length) % bs.length].focus();
    });
    el("kanjiContainer").addEventListener("contextmenu", e => {
      const c = e.target.closest(".card");
      onContext(e, c && c.dataset.char);
    });
    el("treePane").addEventListener("contextmenu", e => {
      const g = e.target.closest(".g");
      onContext(e, g && g.dataset.k);
    });

    /* 一覧とツリーは独立したON/OFFなので、素直にチェック2つで持つ
       （一覧だけ・ツリーだけ・両方の3通り）。両方OFFは何も見えなくなるだけなので押し返す。 */
    const showsList = () => el("showList").checked;
    function applyView(changed) {
      const list = el("showList"), tree = el("showTree");
      if (!list.checked && !tree.checked) {
        if (changed === list && !tree.disabled) tree.checked = true; else list.checked = true;
      }
      document.body.classList.toggle("tree-on", tree.checked);
      document.body.classList.toggle("list-off", !list.checked);
      saveTreeOpen(tree.checked);
      relayout(); // ツリーペインの出入りで一覧の幅もスクロールのしかたも変わる
      // 隠していた側のペインはスクロール位置を保っていないので、残っている側を基準に引き直す
      if (tree.checked) {
        if (treeDirty) rebuildTree(); // 閉じているあいだに変わった一覧を、開くこの時に反映する
        curAnchor = -1; lastListTop = lastTreeTop = -1;
        list.checked ? syncTree() : syncList();
      }
    }
    ["showList", "showTree"].forEach(id => el(id).addEventListener("change", e => {
      if (e.target.id === "showTree") document.body.classList.toggle("tree-sheet", e.target.checked);
      applyView(e.target);
    }));

    el("fontBadge").addEventListener("click", () => {
      useIPAmj = !useIPAmj;
      updateFontBadge();
    });

    // ツリーの左クリックはコピー（字はその字、MJ番号はMJ番号）、右クリックで移動
    el("treePane").addEventListener("click", e => {
      const m = e.target.closest("[data-copy]");
      if (m) { copyText(m.dataset.copy, m.dataset.copy); return; }
      const g = e.target.closest(".g");
      if (g) copyText(g.dataset.c, `「${g.dataset.c}」`);
    });

    /* ツリーに行の無い字の断り書き。今は外している根拠でなら縮退があるときは、その根拠と行き先も添える。
       ツリーを触るか一覧を動かせば消す（window の pointerdown / wheel） */
    function noShrinkNote(ch, nearby) {
      const base = Array.from(ch)[0], by = new Map();   // 根拠の名前 -> 行き先の字
      // mjByChar は入れている根拠の縮退だけで組んであるので、ここは全MJから引く（7万件の走査で済む）
      mjBase.forEach((b, mi) => b === base && mjmap.mj[mi][2].forEach(([ji, bits]) => {
        SRC.forEach(x => {
          if (x.on || !(bits >> x.b & 1) || jisCh[ji] === base) return;
          const label = x.chip ? SRC.find(y => y.id === x.chip).label : x.label;
          if (!by.has(label)) by.set(label, new Set());
          by.get(label).add(jisCh[ji]);
        });
      }));
      const hint = [...by].map(([l, t]) => `「${l}」を入れると ${[...t].join(" ")} へ`).join("、");
      return `「${ch}」は、選んでいる根拠では縮退がありません。${hint ? hint + "縮退します。" : ""}${nearby ? "下は一覧で近くにある字の行です" : ""}`;
    }
    function showTreeNote(text) {
      const n = el("treeNote");
      if (!n) return;
      n.textContent = text;
      n.hidden = !text;
    }

    /* 見えているものは動かさない。外に出ているときだけ、入りきる最小の量だけ送る。
       head は上端に貼り付く見出しのぶんで、その下からが実際に読める範囲になる。
       画面の中の物をわざわざ端へ寄せ直すと、どこから飛んだのか目で追えなくなる。 */
    function minScroll(cur, viewH, head, top, h) {
      if (top - head < cur) return Math.max(0, top - head); // 上へはみ出している
      if (top + h > cur + viewH) return top + h - viewH;    // 下へはみ出している
      return cur;                                           // 見えているので動かさない
    }

    // 一覧の該当カードへスクロールし、ツリーもその行に合わせて1秒光らせる。見つかれば true
    // 光らせる1枚はDOMに触らず添字で持つ。飛んだ先でスクロールが走ると窓が組み直されて、
    // ノードに付けたクラスは16msで消えてしまうため（ツリーの hoverChar と同じ持ち方）
    let flashI = -1, flashTimer = 0;
    function jumpToChar(ch) {
      const i = listOrder.findIndex(it => it.char === ch);
      if (i < 0) return false;
      // 一覧へ飛ぶ操作なので、ツリーだけ表示中でも一覧を出す。閉じているツリーは開かない。
      // 勝手に開くと一覧とツリーが画面に貼り付く表示に変わり、スワイプが一覧の中で尽きて、
      // 上の枠や設定へ戻れなくなる（狭い画面では一覧が全幅なので逃げ場が無い）
      if (!showsList()) { el("showList").checked = true; applyView(); }
      if (treeOn()) document.body.classList.add("tree-sheet");   // 狭い画面ではツリーがシートなので開く（広い画面では効かない）
      driver = "list";
      // 76px は sticky の水準見出しのぶん。下は行が半分で切れないよう少し余分に見る
      const v = listView(), ly = minScroll(v.top, v.h - sheetH(), 76, cardY(i), pitch + 12);
      if (ly !== v.top) listScrollTo(ly);
      hoverChar = ch;
      curAnchor = -1;
      setAnchor(i); // 一覧は横に十数字並ぶのでアンカーは自動判定に任せず対象に固定する
      // 群を畳んだ字は、その字が実際に描かれている群の行へ送る
      let want = treeRows[firstRowOf[i]];
      if (!want || listOrder[want.anchor].char !== ch) want = treeRows[drawnAt.get(ch)] || want;
      // 縮退の無い字はツリーに行を持たないので、送った先は近くの別の字の行になる。そう断っておく
      const own = want && (listOrder[want.anchor].char === ch || drawnAt.get(ch) != null);
      showTreeNote(own ? "" : noShrinkNote(ch, !!want));
      const tp = el("treePane");
      if (want) {
        // 行の y は tree-head のぶんを差し引いた座標なので、上端は head の下に出る。
        // 読める高さはペインから head を除いたぶん。
        const hd = tp.querySelector(".tree-head");
        const ty = minScroll(tp.scrollTop, tp.clientHeight - (hd ? hd.offsetHeight : 0), 0, want.y, want.h + 8);
        if (Math.abs(tp.scrollTop - ty) > 1) { tp.scrollTop = ty; lastTreeTop = tp.scrollTop; }
      }
      renderTreeWindow();

      // ペインは部首フィルタの下にあるので、画面に入っていなければページごと送る
      // （一覧がページのまま流れているときは、上の listScrollTo がもうページを送っている）
      const box = el("kanjiPanes").getBoundingClientRect();
      if (listScrolls() && (box.top > 40 || box.bottom < 120)) {
        window.scrollTo({ top: window.scrollY + box.top - navH() - 8, behavior: "smooth" });
      }

      clearTimeout(flashTimer);
      flashI = i;
      redrawCards(); // 飛んだ先がまだ実体化されていないので、光らせる1枚を入れて組み直す
      flashTimer = setTimeout(() => { flashI = -1; redrawCards(); }, 1000);
      return true;
    }

    /* ---- 検索: 文字 / U+xxxx / MJxxxxxx / 面区点 を受け、当たった字の集合を返す ----
       MJ番号と符号位置は前方一致でも拾う。MJ0068 なら MJ006800〜MJ006899 が、
       U+4F1 なら U+4F10〜U+4F1F がまとめて当たる。桁を全部打てば従来どおり1字になる。
       MJ字形はIVS付きの札でも一覧に出ているので、基底とIVS付きの両方を集合に入れる。 */
    function resolveQuery(q) {
      q = q.trim();
      const out = new Set();
      if (!q) return out;
      let m;
      if (m = /^MJ(\d{1,6})$/i.exec(q)) {
        // 桁を揃えて打っても（MJ0068）、頭の0を省いて打っても（MJ89）前方一致で拾う
        const dig = m[1];
        if (mjmap) mjmap.mj.forEach((x, i) => {
          const n = String(x[0]);
          if (!x[1] || !(n.padStart(6, "0").startsWith(dig) || n.startsWith(dig))) return;
          out.add(mjBase[i]); out.add(x[1]);
        });
        return out;
      }
      if (m = /^U\+?([0-9a-f]{1,6})$/i.exec(q)) {
        const pre = m[1].toUpperCase();
        const hex = c => c.codePointAt(0).toString(16).toUpperCase();
        [1, 2, 3, 4].forEach(lv => allKanjiList[lv].forEach(c => { if (hex(c).startsWith(pre)) out.add(c); }));
        if (mjmap) mjmap.mj.forEach((x, i) => {
          if (!x[1] || !hex(mjBase[i]).startsWith(pre)) return;
          out.add(mjBase[i]); out.add(x[1]);
        });
        return out;
      }
      if (m = /^([12])-(\d{1,2})-(\d{1,2})$/.exec(q)) {
        const ch = jisChar.get(`${m[1]}-${m[2].padStart(2, "0")}-${m[3].padStart(2, "0")}`);
        if (ch) out.add(ch);
        return out;
      }
      Array.from(q).forEach(c => out.add(c));
      return out;
    }

    /* 区の絞り込み。面区（1-16 など）と MJ外字のブロック（CJK拡張A など）を1つの箱に入れ、
       どの水準の区なのかは optgroup で束ねる。面は水準から決まる（第1〜3水準=1面、第4水準=2面）
       ので、面区のほうは mjmap を読んでいなくても効く。 */
    const kuValue = () => el("kuFilter").value;
    const blockValue = () => kuValue().startsWith("blk:") ? kuValue().slice(4) : null;
    function kuMatcher() {
      const v = kuValue();
      if (!v || blockValue()) return null;
      const men = +v.slice(0, 1), ku = +v.slice(2);
      return (level, cardKu) => (level === 4 ? 2 : 1) === men && cardKu === ku;
    }
    function buildKuFilter() {
      const sel = el("kuFilter");
      sel.innerHTML = '<option value="">区: すべて</option>';
      [1, 2, 3, 4].forEach(lv => {
        const men = lv === 4 ? 2 : 1;
        const ks = [...new Set(kuByLevel[lv].map(ku => `${men}-${String(ku).padStart(2, "0")}`))].sort();
        if (!ks.length) return;
        const g = document.createElement("optgroup");
        g.label = `第${lv}水準`;
        ks.forEach(k => g.appendChild(new Option(k, k)));
        sel.appendChild(g);
      });
      sel.addEventListener("change", () => { pushNext = true; runSearch(); });
    }

    /* 外字のブロックは mjmap を読まないと分からないので、読み込んだあとで足す。
       縮退の根拠を切ると外字に回る字が変わるので、そのたびに引き直す。 */
    function fillGaijiBlocks() {
      const sel = el("kuFilter");
      const keep = sel.value;
      const old = sel.querySelector('optgroup[label="MJ外字"]');
      if (old) old.remove();
      const seen = new Set();
      mjmap.mj.forEach((m, i) => {
        if (!m[1]) return;
        const to = candByMj.get(i);
        if (to && to.some(([ji]) => charLevel.has(jisCh[ji]))) return;
        if (SYMBOL_CHARS.has(m[1])) return; // 記号は外字に出さない
        seen.add(cjkBlock(m[1].codePointAt(0)));
      });
      const g = document.createElement("optgroup");
      g.label = "MJ外字";
      CJK_BLOCKS.map(b => b[2]).concat("その他").forEach(name => {
        if (seen.has(name)) g.appendChild(new Option(name, "blk:" + name));
      });
      sel.appendChild(g);
      sel.value = keep;
      if (!sel.value) sel.value = ""; // 消えたブロックを選んでいたら「すべて」に戻す
    }

    function runSearch() {
      const q = el("mjSearch").value.trim();
      renderKanji(); // 検索も絞り込みなので一覧ごと組み直す（末尾で rebuildTree される）
      const st = el("mjmapStatus");
      if (!q) { st.textContent = ""; return; }
      if (!listOrder.length) { st.textContent = "一覧に該当なし"; return; }
      // 一覧が1枚に絞れたときだけ縮退の中身まで出す。前方一致で広く当たったときは件数だけ
      if (listOrder.length !== 1) { st.textContent = `${listOrder.length.toLocaleString()}字が該当`; return; }
      const ch = Array.from(listOrder[0].char)[0]; // 外字のカードはIVS付きなので基底を見る
      const mjs = mjByChar.get(ch) || [];
      const outOf = new Set();
      mjs.forEach(i => (candByMj.get(i) || []).forEach(([ji]) => { if (jisCh[ji] !== ch) outOf.add(mjmap.jis[ji][0]); }));
      st.textContent = `「${ch}」 縮退元 ${mjs.length}字 / 縮退先 ${outOf.size}種 (${[...outOf].sort().join(" ") || "なし"})`;
    }

    // 入力のたびに絞る。一覧の組み直しは重いので少し待つ（IME変換中は確定まで待つ）
    let searchTimer = 0;
    const scheduleSearch = () => { clearTimeout(searchTimer); searchTimer = setTimeout(runSearch, 250); };
    ["input", "compositionend"].forEach(ev =>
      el("mjSearch").addEventListener(ev, e => {
        if (e.isComposing) return;
        // 検索で引くときは部品を外す（setSlot の上の説明）。部品は消えるので、戻せるよう履歴を積む
        if (el("mjSearch").value.trim() && (Object.keys(slots).length || nestSteps.length)) {
          slots = {};
          nestSteps = [];
          closePalette();
          pushNext = true;
        }
        scheduleSearch();
      }));
    ["onlyJinmei", "onlyShrink"].forEach(id => el(id).addEventListener("change", () => { pushNext = true; runSearch(); }));
    // / で検索欄へ（入力中の欄では普通に / を打てる）
    document.addEventListener("keydown", e => {
      if (e.key !== "/" || e.isComposing || e.target.closest("input, textarea, select")) return;
      e.preventDefault();
      el("mjSearch").focus();
    });

    el("mjSearch").addEventListener("keydown", e => {
      if (e.key === "Enter") { clearTimeout(searchTimer); runSearch(); }
    });

    /* 画面に貼り付く一覧（縮退ツリーON の一覧とツリー、変体仮名）は内側でスクロールする。
       ページがまだ上にあるうちにその上でホイールを回すと、ページではなく内側だけが動き、
       検索の枠を上に残したまま狭い領域が送られる。一覧が上端に貼り付くまではページを送る。
       上へ回すときは、内側が先頭まで戻ればブラウザが自然にページへ引き継ぐので触らない */
    /* 上端に貼り付くタブと移動の高さ。貼り付く見出しやペインはこの下に止める。
       移動の札は件数で折り返して高さが変わるので、変わるたびに CSS の --nav-h へ書き戻す */
    const activeJump = () => el(el('hentaigana').classList.contains('active') ? 'kanaJumpRow' : 'kanjiJumpRow');
    const navH = () => el('tabsBar').offsetHeight + activeJump().offsetHeight;
    const syncNavH = () => {
      document.documentElement.style.setProperty('--tabs-h', `${el('tabsBar').offsetHeight}px`);
      document.documentElement.style.setProperty('--nav-h', `${navH()}px`);
    };
    syncNavH();
    if (window.ResizeObserver) { const ro = new ResizeObserver(syncNavH); ['tabsBar', 'kanjiJumpRow', 'kanaJumpRow'].forEach(id => ro.observe(el(id))); }

    function scrollPageFirst(pane, stuckTop, active) {
      pane.addEventListener('wheel', e => {
        if (e.deltaY <= 0 || e.ctrlKey || !active()) return;
        const gap = pane.getBoundingClientRect().top - stuckTop();
        if (gap <= 1) return;
        e.preventDefault();
        const dy = e.deltaMode === 1 ? e.deltaY * 16 : e.deltaMode === 2 ? e.deltaY * innerHeight : e.deltaY;
        window.scrollBy(0, Math.min(dy, gap));
      }, { passive: false });
    }
    scrollPageFirst(el('kanjiPanes'), () => navH() + 8, listScrolls);
    scrollPageFirst(el('hentaiganaContainer'), () => navH() + 8, () => true);

    // 共通ユーティリティ
    function copyText(text, label) {
      navigator.clipboard.writeText(text).then(() => {
        const toast = document.getElementById('toast');
        toast.innerText = `${label} をコピーしました`;
        toast.style.display = 'block';
        setTimeout(() => toast.style.display = 'none', 1500);
      });
    }

    // 初期化実行
    window.onload = () => {
      initData();
      initPartIndex(); // 水準字の索引は一覧と同じデータから組む。外字ぶんは mjmap を読んでから足す
      buildKuFilter(); // 面区の選択肢は initData が並べた区データから作る
      buildRadicalListboxes();
      writeState(hashState()); // URL に条件があれば、それで最初の一覧を描く
      renderKanji();
      renderHentaigana();
      checkIPAmjFont();
      wireSync();
      // http(s) で配信されているときは同じ場所の mjmap.json を毎回取る（GitHub Pages がこれ）。
      // 手元に保存すると、mjmap.json を作り直しても古いデータのまま描かれ、根拠の表示と合わなくなる。
      // file:// のページはオリジンを持たない扱いなので、同じフォルダに置いてあっても fetch は
      // 止められる。そのときだけ、前回ファイル選択で読ませたぶんを IndexedDB から復元する。
      // 黙って未読込のままにすると理由が分からないので、無ければ手動選択を促す。
      (SERVED ? fetch('mjmap.json', { cache: 'no-cache' }).then(r => r.ok ? r.text() : null).then(t => t && { t, src: 'fetch' })
              : idb('readonly', s => s.get('mjmap')).then(t => t && { t, src: 'idb' }))
        .catch(() => null)
        .then(r => {
          if (r) return loadMjmap(r.t, r.src);
          const why = SERVED
            ? 'mjmap.json が見つかりません'
            : `${location.protocol}// で開いているため mjmap.json を自動で読めません`;
          setDataState(false, why + '。クリックして mjmap.json を選んでください');
          el('mjmapStatus').textContent = why + '。「データ」から mjmap.json を選ぶか、ローカルサーバ経由で開いてください';
        });
    };
